test "EndpointConnectionLifecycle pending-work backend loop step selects next deadline" {
    const NoopBackend = struct {
        pulls: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pulls += 1;
            return null;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var idle_conn = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
        .max_idle_timeout_ms = 30,
    });
    defer idle_conn.deinit();
    try idle_conn.confirmHandshake();

    const idle_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const idle_cid = [_]u8{ 0x61, 0x62, 0x63, 0x64 };
    try lifecycle.registerConnectionId(191, &idle_cid, idle_path, .{ .sequence_number = 0 });

    try idle_conn.sendPing();
    var idle_payload_buf: [16]u8 = undefined;
    _ = (try idle_conn.pollTx(10 * ms, &idle_payload_buf)) orelse return error.TestUnexpectedResult;
    const idle_deadline = idle_conn.idleTimeoutDeadline() orelse return error.TestUnexpectedResult;

    var backend_connection = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer backend_connection.deinit();
    try backend_connection.confirmHandshake();
    _ = try backend_connection.recordPacketSentInSpace(.application, 20 * ms, 100);

    var backend = NoopBackend{};
    var scratch: [8]u8 = undefined;
    const pending_connections = [_]EndpointConnectionReceiveView{
        .{ .connection_id = 191, .connection = &idle_conn },
        .{ .connection_id = 192, .connection = &backend_connection },
    };
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 192,
        .connection = &backend_connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const deadline_connections = [_]EndpointConnectionView{
        .{ .connection_id = 191, .connection = &idle_conn },
        .{ .connection_id = 192, .connection = &backend_connection },
    };

    const result = try lifecycle.processPendingWorkStepWithCryptoDeadline(&pending_connections, idle_deadline, &.{.handshake}, &drive_views, .{}, &.{}, &deadline_connections);

    try std.testing.expectEqual(@as(usize, 1), result.pending_work.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.close_retired_count);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(ConnectionState.closed, idle_conn.connectionState());
    try std.testing.expectEqual(ConnectionState.active, backend_connection.connectionState());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.connections_driven);
    try std.testing.expectEqual(@as(usize, 1), backend.pulls);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());
    const next = result.backend.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 192), next.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, next.kind);
    const recovery_timer = next.recovery orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(PacketNumberSpace.application, recovery_timer.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, recovery_timer.kind);
    try std.testing.expectEqual(@as(?[]const u8, null), try backend_connection.pollTxInSpace(.handshake, 30, &scratch));
}

test "EndpointConnectionLifecycle pending-work cross-space backend loop step selects next deadline" {
    const Backend = struct {
        pulls: usize = 0,
        handshake_sent: bool = false,
        application_sent: bool = false,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pulls += 1;
            const payload = switch (space) {
                .handshake => blk: {
                    if (self.handshake_sent) return null;
                    self.handshake_sent = true;
                    break :blk "timer handshake";
                },
                .application => blk: {
                    if (self.application_sent) return null;
                    self.application_sent = true;
                    break :blk "timer application";
                },
                else => return null,
            };
            if (out_buf.len < payload.len) return error.BufferTooSmall;
            @memcpy(out_buf[0..payload.len], payload);
            return out_buf[0..payload.len];
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var timer_connection = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer timer_connection.deinit();
    try timer_connection.confirmHandshake();
    _ = try timer_connection.recordPacketSentInSpace(.application, 20 * ms, 100);
    try lifecycle.armRecoveryTimerFromConnection(301, &timer_connection);
    const recovery_before = lifecycle.nextDeadline(301, &timer_connection) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, recovery_before.kind);

    var backend_connection = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer backend_connection.deinit();
    try backend_connection.confirmHandshake();

    var backend = Backend{};
    var scratch: [64]u8 = undefined;
    const pending_connections = [_]EndpointConnectionReceiveView{
        .{ .connection_id = 301, .connection = &timer_connection },
        .{ .connection_id = 302, .connection = &backend_connection },
    };
    const backend_spaces = [_]PacketNumberSpace{ .handshake, .application };
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 302,
        .connection = &backend_connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const deadline_connections = [_]EndpointConnectionView{
        .{ .connection_id = 301, .connection = &timer_connection },
        .{ .connection_id = 302, .connection = &backend_connection },
    };

    const result = try lifecycle.processPendingWorkStepWithCryptoDeadline(&pending_connections, recovery_before.deadline_nanos, &backend_spaces, &drive_views, .{}, &.{}, &deadline_connections);

    try std.testing.expectEqual(@as(usize, 0), result.pending_work.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.close_retired_count);
    try std.testing.expectEqual(@as(usize, 1), result.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.connections_driven);
    try std.testing.expectEqual(@as(usize, 4), backend.pulls);
    var tx_buf: [128]u8 = undefined;
    const handshake_payload = (try backend_connection.pollTxInSpace(.handshake, 30, &tx_buf)) orelse return error.TestUnexpectedResult;
    var handshake_decoded = try frame.decodeFrameSlice(handshake_payload, std.testing.allocator);
    defer frame.deinitFrame(&handshake_decoded.frame, std.testing.allocator);
    switch (handshake_decoded.frame) {
        .crypto => |crypto| try std.testing.expectEqualStrings("timer handshake", crypto.data),
        else => return error.TestUnexpectedResult,
    }
    const application_payload = (try backend_connection.pollTxInSpace(.application, 31, &tx_buf)) orelse return error.TestUnexpectedResult;
    var application_decoded = try frame.decodeFrameSlice(application_payload, std.testing.allocator);
    defer frame.deinitFrame(&application_decoded.frame, std.testing.allocator);
    switch (application_decoded.frame) {
        .crypto => |crypto| try std.testing.expectEqualStrings("timer application", crypto.data),
        else => return error.TestUnexpectedResult,
    }
    const next = result.backend.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 301), next.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, next.kind);
    try std.testing.expect(next.deadline_nanos > recovery_before.deadline_nanos);
}

test "EndpointConnectionLifecycle pending-work cross-space close backend loop returns current deadline on peer error" {
    const BadBackend = struct {
        peer_sent: bool = false,
        pulls: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
                .pull_peer_transport_parameters = pullPeerTransportParameters,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, _: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pulls += 1;
            if (out_buf.len == 0) return error.BufferTooSmall;
            out_buf[0] = 0;
            return out_buf[0..1];
        }

        fn pullPeerTransportParameters(context: *anyopaque, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (self.peer_sent) return null;
            if (out_buf.len == 0) return error.BufferTooSmall;
            out_buf[0] = 0x04;
            self.peer_sent = true;
            return out_buf[0..1];
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var connection = try Connection.init(std.testing.allocator, .server, .{});
    defer connection.deinit();
    try connection.validatePeerAddress();

    var backend = BadBackend{};
    var scratch: [64]u8 = undefined;
    const pending_connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 303,
        .connection = &connection,
    }};
    const backend_spaces = [_]PacketNumberSpace{ .handshake, .application };
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 303,
        .connection = &connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const deadline_connections = [_]EndpointConnectionView{.{
        .connection_id = 303,
        .connection = &connection,
    }};

    const result = try lifecycle.processPendingWorkStepWithCryptoDeadline(&pending_connections, 10, &backend_spaces, &drive_views, .{ .close_on_error = true }, &.{}, &deadline_connections);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(@as(usize, 0), result.backend.backend.connections_driven);
    try std.testing.expect(result.backend.next_deadline == null);
    try std.testing.expect(backend.peer_sent);
    try std.testing.expectEqual(@as(usize, 0), backend.pulls);
    try std.testing.expectEqual(ConnectionState.closing, connection.connectionState());
}

test "EndpointConnectionLifecycle pending-work close backend loop step selects next deadline" {
    const NoopBackend = struct {
        pulls: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pulls += 1;
            return null;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var idle_conn = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
        .max_idle_timeout_ms = 30,
    });
    defer idle_conn.deinit();
    try idle_conn.confirmHandshake();

    const idle_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const idle_cid = [_]u8{ 0x71, 0x72, 0x73, 0x74 };
    try lifecycle.registerConnectionId(193, &idle_cid, idle_path, .{ .sequence_number = 0 });

    try idle_conn.sendPing();
    var idle_payload_buf: [16]u8 = undefined;
    _ = (try idle_conn.pollTx(10 * ms, &idle_payload_buf)) orelse return error.TestUnexpectedResult;
    const idle_deadline = idle_conn.idleTimeoutDeadline() orelse return error.TestUnexpectedResult;

    var backend_connection = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer backend_connection.deinit();
    try backend_connection.confirmHandshake();
    _ = try backend_connection.recordPacketSentInSpace(.application, 20 * ms, 100);

    var backend = NoopBackend{};
    var scratch: [8]u8 = undefined;
    const pending_connections = [_]EndpointConnectionReceiveView{
        .{ .connection_id = 193, .connection = &idle_conn },
        .{ .connection_id = 194, .connection = &backend_connection },
    };
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 194,
        .connection = &backend_connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const deadline_connections = [_]EndpointConnectionView{
        .{ .connection_id = 193, .connection = &idle_conn },
        .{ .connection_id = 194, .connection = &backend_connection },
    };

    const result = try lifecycle.processPendingWorkStepWithCryptoDeadline(&pending_connections, idle_deadline, &.{.handshake}, &drive_views, .{ .close_on_error = true }, &.{}, &deadline_connections);

    try std.testing.expectEqual(@as(usize, 1), result.pending_work.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.close_retired_count);
    try std.testing.expectEqual(@as(usize, 0), result.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(ConnectionState.closed, idle_conn.connectionState());
    try std.testing.expectEqual(ConnectionState.active, backend_connection.connectionState());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.connections_driven);
    try std.testing.expectEqual(@as(usize, 1), backend.pulls);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());
    const next = result.backend.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 194), next.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, next.kind);
    const recovery_timer = next.recovery orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(PacketNumberSpace.application, recovery_timer.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, recovery_timer.kind);
    try std.testing.expectEqual(@as(?[]const u8, null), try backend_connection.pollTxInSpace(.handshake, 30, &scratch));
}

test "EndpointConnectionLifecycle pending-work close backend poll keeps explicit zero RTT output" {
    const CountingBackend = struct {
        pulls: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pulls += 1;
            return null;
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x7a, 0x8a, 0x9a, 0xaa };
    const server_dcid = [_]u8{ 0x08, 0x18, 0x28, 0x38 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer client.deinit();
    try client.installZeroRttTrafficSecrets(.{ .local = secrets.client.secret });
    try client.confirmHandshake();
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "bye", false);
    try client.resetStream(stream_id, 111);
    const reset_frame: frame.ResetStreamFrame = .{
        .stream_id = stream_id,
        .application_error_code = 111,
        .final_size = 3,
    };

    var backend_connection = try Connection.init(std.testing.allocator, .server, .{});
    defer backend_connection.deinit();
    try backend_connection.validatePeerAddress();
    var backend = CountingBackend{};
    var scratch: [16]u8 = undefined;

    const options: EndpointPollInstalledKeyDatagramOptions = .{
        .space = .zero_rtt,
        .destination_connection_id = &server_dcid,
        .source_connection_id = &client_dcid,
    };
    const first = (try lifecycle.pollDatagram(219, &client, 10, options)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(first);
    const deadline = lifecycle.nextDeadline(219, &client) orelse return error.TestUnexpectedResult;
    const timer = deadline.recovery orelse return error.TestUnexpectedResult;

    const pending_connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 219,
        .connection = &client,
    }};
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 220,
        .connection = &backend_connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const poll_views = [_]EndpointConnectionInstalledKeyPollView{.{
        .connection_id = 219,
        .connection = &client,
        .poll_options = options,
    }};

    const result = try lifecycle.processPendingWorkStepWithCryptoInstalledKeyPoll(&pending_connections, timer.deadline_nanos, &.{.handshake}, &drive_views, .{ .close_on_error = true }, &.{}, &poll_views);
    try std.testing.expectEqual(@as(usize, 1), result.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.connections_driven);
    try std.testing.expectEqual(@as(usize, 1), backend.pulls);
    const probe = result.backend.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(probe.datagram);
    try std.testing.expectEqual(@as(u64, 219), probe.connection_id);
    try std.testing.expectEqual(@as(usize, 2), client.sentPacketCount(.application));
    try std.testing.expectEqual(@as(u8, 1), client.recovery_state.pto_count);
    try std.testing.expect(try protectedZeroRttContainsControlFrame(
        probe.datagram,
        secrets.client,
        1,
        .{ .reset_stream = reset_frame },
    ));
}

