    }};
    const compatible_drain = try lifecycle.feedStepWithPendingWorkCryptoInstalledKeyDrain(&_w9_receive_connections, path, 15, &ignored_datagram, feed_options, &.{.handshake}, &_w9_drive_views, .{ .compatible_version = true }, &compatibilities, &poll_views, &drained);
    try std.testing.expectEqual(EndpointFeedInstalledKeyDatagramResult.dropped, compatible_drain.feed);
    try std.testing.expectEqual(@as(?EndpointCryptoBackendDriveDatagramDrainResult, null), compatible_drain.backend);

    const _w8_receive_connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 342,
        .connection = &connection,
    }};
    const _w8_drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 342,
        .connection = &connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const compatible_close_poll = try lifecycle.feedStepWithPendingWorkCryptoInstalledKeyPoll(&_w8_receive_connections, path, 16, &ignored_datagram, feed_options, &.{.handshake}, &_w8_drive_views, .{ .close_on_error = true, .compatible_version = true }, &compatibilities, &poll_views);
    try std.testing.expectEqual(EndpointFeedInstalledKeyDatagramResult.dropped, compatible_close_poll.feed);
    try std.testing.expectEqual(@as(?EndpointCryptoBackendDriveDatagramResult, null), compatible_close_poll.backend);

    const _w15_receive_connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 342,
        .connection = &connection,
    }};
    const _w15_drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 342,
        .connection = &connection,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const compatible_close_drain = try lifecycle.feedStepWithPendingWorkCryptoInstalledKeyDrain(&_w15_receive_connections, path, 17, &ignored_datagram, feed_options, &.{.handshake}, &_w15_drive_views, .{ .close_on_error = true, .compatible_version = true }, &compatibilities, &poll_views, &drained);
    try std.testing.expectEqual(EndpointFeedInstalledKeyDatagramResult.dropped, compatible_close_drain.feed);
    try std.testing.expectEqual(@as(?EndpointCryptoBackendDriveDatagramDrainResult, null), compatible_close_drain.backend);
    try std.testing.expectEqual(@as(usize, 0), backend.pulls);
}

test "EndpointConnectionLifecycle feeds installed-key datagram then polls ACK output" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x31, 0x42, 0x53, 0x64 };
    const server_dcid = [_]u8{ 0xc1, 0xd2, 0xe3, 0xf4 };
    const decoy_dcid = [_]u8{ 0xc2, 0xd3, 0xe4, 0xf5 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client_lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer client_lifecycle.deinit();
    var server_lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer server_lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    var decoy = try Connection.init(std.testing.allocator, .server, .{});
    defer decoy.deinit();
    try server.validatePeerAddress();
    try decoy.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();
    try decoy.confirmHandshake();

    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });
    try decoy.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    const client_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
    };
    const server_path = endpoint.Udp4Tuple{
        .local = client_path.remote,
        .remote = client_path.local,
    };
    try client_lifecycle.registerConnectionId(181, &client_dcid, client_path, .{ .sequence_number = 0 });
    try server_lifecycle.registerConnectionId(182, &server_dcid, server_path, .{ .sequence_number = 0 });
    try server_lifecycle.registerConnectionId(183, &decoy_dcid, server_path, .{ .sequence_number = 1 });

    var feed_out: [64]u8 = undefined;
    const reset_prefix = [_]u8{ 0x40, 0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0xde };
    const versions = [_]packet.Version{.v1};
    const feed_options = EndpointFeedInstalledKeyDatagramOptions{
        .space = .application,
        .out = &feed_out,
        .unpredictable_prefix = &reset_prefix,
        .supported_versions = &versions,
    };

    try client.sendPing();
    const first_ping = (try client_lifecycle.pollDatagram(181, &client, 10, .{
        .space = .application,
        .destination_connection_id = &server_dcid,
    })) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(first_ping);
    try server.sendPing();

    const receive_connections = [_]EndpointConnectionReceiveView{
        .{ .connection_id = 183, .connection = &decoy },
        .{ .connection_id = 182, .connection = &server },
    };
    const poll_views = [_]EndpointConnectionPollView{.{
        .connection_id = 182,
        .connection = &server,
        .destination_connection_id = &client_dcid,
    }};
    const first = try server_lifecycle.feedDatagramWithInstalledKeysAcrossConnectionsAndPollDatagram(
        &receive_connections,
        server_path,
        11,
        first_ping,
        feed_options,
        &poll_views,
        .application,
    );
    switch (first.feed) {
        .routed => |route| try std.testing.expectEqual(@as(u64, 182), route.connection_id),
        else => return error.TestUnexpectedResult,
    }
    const first_ack = first.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(first_ack.datagram);
    try std.testing.expectEqual(@as(u64, 182), first_ack.connection_id);
    const first_deadline = first.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 182), first_deadline.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, first_deadline.kind);
    try std.testing.expectEqual(PacketNumberSpace.application, first_deadline.recovery.?.space);
    try std.testing.expectEqual(@as(?u64, null), server.pendingAckLargest(.application));
    try std.testing.expectEqual(@as(?u64, null), decoy.pendingAckLargest(.application));

    try client_lifecycle.processProtectedShortDatagramWithInstalledKeys(
        181,
        &client,
        12,
        client_dcid.len,
        first_ack.datagram,
    );
    try std.testing.expectEqual(@as(usize, 0), client.sentPacketCount(.application));
    try std.testing.expectEqual(@as(usize, 0), client.bytesInFlight(.application));

    try client.sendPing();
    const second_ping = (try client_lifecycle.pollDatagram(181, &client, 13, .{
        .space = .application,
        .destination_connection_id = &server_dcid,
    })) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(second_ping);

    const _w701_receive_connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 182,
        .connection = &server,
    }};
    const _w701_poll_views = [_]EndpointConnectionPollView{.{
        .connection_id = 182,
        .connection = &server,
        .destination_connection_id = &client_dcid,
        .source_connection_id = &[_]u8{},
    }};
    const second = try server_lifecycle.feedDatagramWithInstalledKeysAcrossConnectionsAndPollDatagram(
        &_w701_receive_connections,
        server_path,
        14,
        second_ping,
        feed_options,
        &_w701_poll_views,
        .application,
    );
    switch (second.feed) {
        .routed => |route| try std.testing.expectEqual(@as(u64, 182), route.connection_id),
        else => return error.TestUnexpectedResult,
    }
    const second_ack = second.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(second_ack.datagram);
    try std.testing.expectEqual(@as(u64, 182), second_ack.connection_id);
    try std.testing.expectEqual(@as(?EndpointConnectionDeadline, null), second.next_deadline);

    try client_lifecycle.processProtectedShortDatagramWithInstalledKeys(
        181,
        &client,
        15,
        client_dcid.len,
        second_ack.datagram,
    );
    try std.testing.expectEqual(@as(usize, 0), client.sentPacketCount(.application));
    try std.testing.expectEqual(@as(usize, 0), client.bytesInFlight(.application));
    try std.testing.expectEqual(@as(usize, 0), client_lifecycle.recoveryTimerCount());
}

