            .destination_connection_id = &first_dcid,
        },
        .{
            .connection_id = 104,
            .connection = &second,
            .destination_connection_id = &second_dcid,
        },
    };

    var first_batch: [1]EndpointPolledDatagramResult = undefined;
    const first_result = lifecycle.drainDatagramsAcrossConnections(
        &connections,
        10,
        .application,
        &first_batch,
    );
