        error.InvalidPacket,
        lifecycle.driveCryptoBackendStepWithPoll(&.{.handshake}, &_w117_drive_views, .{ .close_on_error = true, .compatible_version = true }, &[_]VersionCompatibility{}, &_w117_poll_views, 10, .{
            .space = .handshake,
