    defer client.deinit();
    try client.installZeroRttTrafficSecrets(.{ .local = secrets.client.secret });
    try client.confirmHandshake();
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "bye", false);
    try client.resetStream(stream_id, 141);
    const reset_frame: frame.ResetStreamFrame = .{
        .stream_id = stream_id,
        .application_error_code = 141,
        .final_size = 3,
    };

    var backend = Backend{ .peer_transport_parameters = peer_params_out.getWritten() };
    var scratch: [256]u8 = undefined;
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 142,
        .connection = &server,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const poll_views = [_]EndpointConnectionInstalledKeyPollView{.{
        .connection_id = 143,
        .connection = &client,
        .poll_options = .{
            .space = .zero_rtt,
            .destination_connection_id = &server_dcid,
            .source_connection_id = &client_dcid,
        },
    }};

    const result = try lifecycle.driveCryptoBackendStepWithInstalledKeyPoll(&.{.handshake}, &drive_views, .{ .close_on_error = true, .compatible_version = true }, &compatibilities, &poll_views, 10);
    try std.testing.expectEqual(@as(usize, 1), result.backend.connections_driven);
    try std.testing.expectEqual(@as(?packet.Version, packet.Version.v2), result.backend.progress.peer_compatible_version_selected);
    try std.testing.expectEqual(@as(u64, 12_864), server.peer_max_data);
    try std.testing.expect(backend.peer_sent);
    const polled = result.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(polled.datagram);
    try std.testing.expectEqual(@as(u64, 143), polled.connection_id);
    try std.testing.expectEqual(@as(usize, 1), client.sentPacketCount(.application));
    try std.testing.expect(try protectedZeroRttContainsControlFrame(
        polled.datagram,
        secrets.client,
        0,
        .{ .reset_stream = reset_frame },
    ));
}

test "EndpointConnectionLifecycle compatible close backend drive drains explicit installed-key output" {
    const Backend = struct {
        peer_transport_parameters: []const u8,
        peer_sent: bool = false,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
                .pull_peer_transport_parameters = pullPeerTransportParameters,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(_: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            return null;
        }

        fn pullPeerTransportParameters(context: *anyopaque, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (self.peer_sent) return null;
            if (out_buf.len < self.peer_transport_parameters.len) return error.BufferTooSmall;
            @memcpy(out_buf[0..self.peer_transport_parameters.len], self.peer_transport_parameters);
            self.peer_sent = true;
            return out_buf[0..self.peer_transport_parameters.len];
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const first_client_dcid = [_]u8{ 0xab, 0xbb, 0xcb, 0xdb };
    const first_server_dcid = [_]u8{ 0x39, 0x49, 0x59, 0x69 };
    const second_client_dcid = [_]u8{ 0xac, 0xbc, 0xcc, 0xdc };
    const second_server_dcid = [_]u8{ 0x3a, 0x4a, 0x5a, 0x6a };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const client_versions = [_]packet.Version{ .v1, .v2 };
    const server_versions = [_]packet.Version{ .v2, .v1 };
    const compatibilities = [_]VersionCompatibility{.{
        .original_version = .v1,
        .negotiated_version = .v2,
    }};

    var peer_params_buf: [128]u8 = undefined;
    var peer_params_out = buffer.fixedWriter(&peer_params_buf);
    try transport_parameters.encode(peer_params_out.writer(), .{
        .initial_max_data = 13_975,
        .version_information = .{
            .chosen_version = .v1,
            .available_versions = &client_versions,
        },
    });

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var server = try Connection.init(std.testing.allocator, .server, .{
        .chosen_version = .v2,
        .available_versions = &server_versions,
    });
    defer server.deinit();
    try server.validatePeerAddress();

    var first = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer first.deinit();
    try first.installZeroRttTrafficSecrets(.{ .local = secrets.client.secret });
    try first.confirmHandshake();
    const first_stream_id = try first.openStream();
    try first.sendOnStream(first_stream_id, "bye", false);
    try first.resetStream(first_stream_id, 142);
    const first_reset_frame: frame.ResetStreamFrame = .{
        .stream_id = first_stream_id,
        .application_error_code = 142,
        .final_size = 3,
    };

    var second = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer second.deinit();
    try second.installZeroRttTrafficSecrets(.{ .local = secrets.client.secret });
    try second.confirmHandshake();
    const second_stream_id = try second.openStream();
    try second.sendOnStream(second_stream_id, "bye", false);
    try second.resetStream(second_stream_id, 143);
    const second_reset_frame: frame.ResetStreamFrame = .{
        .stream_id = second_stream_id,
        .application_error_code = 143,
        .final_size = 3,
    };

    var backend = Backend{ .peer_transport_parameters = peer_params_out.getWritten() };
    var scratch: [256]u8 = undefined;
    const drive_views = [_]EndpointCryptoBackendDriveView{.{
        .connection_id = 144,
        .connection = &server,
        .backend = backend.backend(),
        .scratch = &scratch,
    }};
    const poll_views = [_]EndpointConnectionInstalledKeyPollView{
        .{
            .connection_id = 145,
            .connection = &first,
            .poll_options = .{
                .space = .zero_rtt,
                .destination_connection_id = &first_server_dcid,
                .source_connection_id = &first_client_dcid,
            },
        },
        .{
            .connection_id = 146,
            .connection = &second,
            .poll_options = .{
                .space = .zero_rtt,
                .destination_connection_id = &second_server_dcid,
                .source_connection_id = &second_client_dcid,
            },
        },
    };
    var out: [2]EndpointPolledDatagramResult = undefined;

    const result = try lifecycle.driveCryptoBackendStepWithInstalledKeyDrain(
        &.{.handshake},
        &drive_views,
        .{ .close_on_error = true, .compatible_version = true },
        &compatibilities,
        &poll_views,
        10,
        &out,
    );
    try std.testing.expectEqual(@as(usize, 1), result.backend.connections_driven);
    try std.testing.expectEqual(@as(?packet.Version, packet.Version.v2), result.backend.progress.peer_compatible_version_selected);
    try std.testing.expectEqual(@as(u64, 13_975), server.peer_max_data);
    try std.testing.expect(backend.peer_sent);
    try std.testing.expectEqual(@as(usize, 2), result.drain.datagrams_written);
    try std.testing.expectEqual(@as(?Error, null), result.drain.first_error);
    defer std.testing.allocator.free(out[0].datagram);
    defer std.testing.allocator.free(out[1].datagram);
    try std.testing.expectEqual(@as(u64, 145), out[0].connection_id);
    try std.testing.expectEqual(@as(u64, 146), out[1].connection_id);
    try std.testing.expect(try protectedZeroRttContainsControlFrame(
        out[0].datagram,
        secrets.client,
        0,
        .{ .reset_stream = first_reset_frame },
    ));
    try std.testing.expect(try protectedZeroRttContainsControlFrame(
        out[1].datagram,
        secrets.client,
        0,
        .{ .reset_stream = second_reset_frame },
    ));
}

test "EndpointConnectionLifecycle retires route and timer after idle timeout closes connection" {
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var conn = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
        .max_idle_timeout_ms = 30,
    });
    defer conn.deinit();
    try conn.confirmHandshake();

    const path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const cid0 = [_]u8{ 0x41, 0x41, 0x41, 0x41 };
    const cid1 = [_]u8{ 0x42, 0x42, 0x42, 0x42 };
    try lifecycle.registerConnectionId(55, &cid0, path, .{ .sequence_number = 0 });
    try lifecycle.registerConnectionId(55, &cid1, path, .{ .sequence_number = 1 });

    try conn.sendPing();
    var out_buf: [16]u8 = undefined;
    const payload = (try conn.pollTx(10 * ms, &out_buf)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), payload.len);
    try lifecycle.armRecoveryTimerFromConnection(55, &conn);
    try std.testing.expectEqual(@as(usize, 2), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    try std.testing.expectEqual(@as(?i64, 40 * ms), conn.idleTimeoutDeadline());
    try std.testing.expectEqual(
        @as(?EndpointConnectionRetireResult, null),
        try lifecycle.checkIdleTimeoutsAndRetireConnection(55, &conn, 39 * ms),
    );
    try std.testing.expectEqual(ConnectionState.active, conn.connectionState());
    try std.testing.expectEqual(@as(usize, 2), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    const retired = (try lifecycle.checkIdleTimeoutsAndRetireConnection(55, &conn, 40 * ms)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(ConnectionState.closed, conn.connectionState());
    try std.testing.expectEqual(@as(usize, 2), retired.routes_retired);
    try std.testing.expect(retired.recovery_timer_disarmed);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());
}

test "EndpointConnectionLifecycle retires route and timer after close timeout closes connection" {
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    const path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const closing_cid = [_]u8{ 0x43, 0x43, 0x43, 0x43 };
    const draining_cid = [_]u8{ 0x44, 0x44, 0x44, 0x44 };

    var closing = try Connection.init(std.testing.allocator, .client, .{ .initial_rtt_ns = 100 });
    defer closing.deinit();
    try closing.confirmHandshake();
    try lifecycle.registerConnectionId(56, &closing_cid, path, .{ .sequence_number = 0 });
    _ = try closing.recordPacketSentInSpace(.application, 10 * ms, 100);
    try lifecycle.armRecoveryTimerFromConnection(56, &closing);
    try closing.closeConnection(0, @backingInt(frame.FrameType.ping), "done");
    var out_buf: [64]u8 = undefined;
    _ = (try closing.pollTx(11 * ms, &out_buf)) orelse return error.TestUnexpectedResult;
    const closing_deadline = closing.closeDeadline() orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(
        @as(?EndpointConnectionRetireResult, null),
        try lifecycle.checkCloseTimeoutsAndRetireConnection(56, &closing, closing_deadline - 1),
    );
    try std.testing.expectEqual(ConnectionState.closing, closing.connectionState());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    const closing_retired = (try lifecycle.checkCloseTimeoutsAndRetireConnection(56, &closing, closing_deadline)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(ConnectionState.closed, closing.connectionState());
    try std.testing.expectEqual(@as(usize, 1), closing_retired.routes_retired);
    try std.testing.expect(closing_retired.recovery_timer_disarmed);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());

    var draining = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer draining.deinit();
    try draining.confirmHandshake();
    try draining.validatePeerAddress();
    try lifecycle.registerConnectionId(57, &draining_cid, path, .{ .sequence_number = 0 });
    _ = try draining.recordPacketSentInSpace(.application, 20 * ms, 100);
    try lifecycle.armRecoveryTimerFromConnection(57, &draining);

    var close_buf: [64]u8 = undefined;
    var close_out = buffer.fixedWriter(&close_buf);
    try frame.encodeFrame(close_out.writer(), .{ .application_close = .{
        .error_code = 0,
        .reason_phrase = "remote",
    } });
    try draining.processDatagram(21 * ms, close_out.getWritten());
    const draining_deadline = draining.closeDeadline() orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(
        @as(?EndpointConnectionRetireResult, null),
        try lifecycle.checkCloseTimeoutsAndRetireConnection(57, &draining, draining_deadline - 1),
    );
    try std.testing.expectEqual(ConnectionState.draining, draining.connectionState());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    const draining_retired = (try lifecycle.checkCloseTimeoutsAndRetireConnection(57, &draining, draining_deadline)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(ConnectionState.closed, draining.connectionState());
    try std.testing.expectEqual(@as(usize, 1), draining_retired.routes_retired);
    try std.testing.expect(draining_retired.recovery_timer_disarmed);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());
}

test "EndpointConnectionLifecycle processes Version Negotiation and retires old attempt" {
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    const path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const client_versions = [_]packet.Version{ .v2, .v1 };
    const server_versions = [_]packet.Version{.v2};

    var raw: [64]u8 = undefined;
    var out = buffer.fixedWriter(&raw);
    try packet.encodeVersionNegotiationPacket(out.writer(), .{
        .dcid = &client_scid,
        .scid = &original_dcid,
        .versions = &server_versions,
    });

    var client = try Connection.init(std.testing.allocator, .client, .{
        .chosen_version = .v1,
        .available_versions = &client_versions,
    });
    defer client.deinit();

    _ = try lifecycle.registerClientInitialSourceConnectionId(91, &client_scid, path, .{});
    _ = try client.recordPacketSentInSpace(.initial, 0 * ms, 1200);
    try lifecycle.armRecoveryTimerFromConnection(91, &client);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    const result = (try lifecycle.processVersionNegotiationDatagram(
        91,
        &client,
        10,
        &original_dcid,
        &client_scid,
        out.getWritten(),
    )) orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(packet.Version.v2, result.selected_version);
    try std.testing.expectEqual(packet.Version.v2, client.versionNegotiationSelectedVersion().?);
    try std.testing.expectEqual(packet.Version.v2, result.followup_config.chosen_version);
    try std.testing.expectEqual(packet.Version.v2, result.followup_config.version_negotiation_selected_version.?);
    try std.testing.expectEqualSlices(packet.Version, &client_versions, result.followup_config.available_versions);
    try std.testing.expectEqual(@as(usize, 1), result.retired.routes_retired);
    try std.testing.expect(result.retired.recovery_timer_disarmed);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.routeCount());
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());
}

