test "EndpointConnectionLifecycle installed-key path update commits after PATH_RESPONSE validation" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    const old_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const new_path = endpoint.Udp4Tuple{
        .local = old_path.local,
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_001),
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();
    try lifecycle.registerConnectionId(88, &server_dcid, old_path, .{});

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    // PING 从新路径到达：检测 path_changed，但不 commit（outstanding 未减少）。
    try client.sendPing();
    const migrated_ping = (try client.pollProtectedShortDatagramWithInstalledKeys(1 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(migrated_ping);
    const ping_result = try lifecycle.processRoutedProtectedShortDatagramWithInstalledKeysAndUpdatePathOrClose(
        88,
        &server,
        new_path,
        2,
        migrated_ping,
    );
    try std.testing.expect(ping_result.route.path_changed);
    try std.testing.expect(ping_result.updated_route == null);
    try std.testing.expectEqual(@as(usize, 0), server.outstandingPathChallengeCount());

    // PATH_CHALLENGE/RESPONSE 交换后，outstanding 1->0 触发 route commit。
    const challenge_data = [_]u8{ 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb };
    try server.sendPathChallenge(challenge_data);
    const challenge = (try server.pollProtectedShortDatagramWithInstalledKeys(3 * ms, &client_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(challenge);
    try std.testing.expectEqual(@as(usize, 1), server.outstandingPathChallengeCount());
    try client.processProtectedShortDatagramWithInstalledKeys(4 * ms, client_dcid.len, challenge);

    const response = (try client.pollProtectedShortDatagramWithInstalledKeys(5 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(response);
    const validation_result = try lifecycle.processRoutedProtectedShortDatagramWithInstalledKeysAndUpdatePathOrClose(
        88,
        &server,
        new_path,
        6,
        response,
    );
    try std.testing.expect(validation_result.route.path_changed);
    const updated_route = validation_result.updated_route orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 88), updated_route.connection_id);
    try std.testing.expect(!updated_route.path_changed);
    try std.testing.expectEqual(@as(usize, 0), server.outstandingPathChallengeCount());

    const confirmed_route = try lifecycle.routeDatagram(new_path, response);
    try std.testing.expectEqual(@as(u64, 88), confirmed_route.connection_id);
    try std.testing.expect(!confirmed_route.path_changed);
}

test "EndpointConnectionLifecycle feed installed-key path update commits after PATH_RESPONSE validation" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const challenge_data = [_]u8{ 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb };
    const options = EndpointFeedInstalledKeyDatagramOptions{
        .space = .application,
        .out = &[_]u8{},
        .unpredictable_prefix = &[_]u8{},
        .supported_versions = &[_]packet.Version{.v1},
        .path_challenge_data = challenge_data,
    };

    const old_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const new_path = endpoint.Udp4Tuple{
        .local = old_path.local,
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_001),
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();
    try lifecycle.registerConnectionId(188, &server_dcid, old_path, .{});

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    try client.sendPing();
    const migrated_ping = (try client.pollProtectedShortDatagramWithInstalledKeys(1 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(migrated_ping);
    const ping_result = try lifecycle.feedDatagramWithInstalledKeysAndUpdatePathOrCloseAndPollDatagram(
        188,
        &server,
        new_path,
        2,
        migrated_ping,
        options,
        .{
            .space = .application,
            .destination_connection_id = &client_dcid,
        },
    );
    const ping_route = switch (ping_result.feed.feed) {
        .routed => |route| route,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(ping_route.path_changed);
    try std.testing.expect(ping_result.feed.updated_route == null);
    try std.testing.expect(ping_result.feed.path_challenge_queued);
    try std.testing.expect((ping_result.feed.selected_output_path orelse return error.TestUnexpectedResult).eql(new_path));
    try std.testing.expect((ping_result.output_path orelse return error.TestUnexpectedResult).eql(new_path));
    const challenge_packet = ping_result.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(challenge_packet.datagram);
    try std.testing.expectEqual(@as(u64, 188), challenge_packet.connection_id);
    const ping_next_deadline = ping_result.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 188), ping_next_deadline.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, ping_next_deadline.kind);
    try std.testing.expectEqual(@as(usize, 0), server.pendingPathChallengeCount());
    try std.testing.expectEqual(@as(usize, 1), server.outstandingPathChallengeCount());
    try std.testing.expect((try lifecycle.routeDatagram(new_path, migrated_ping)).path_changed);

    try client.sendPing();
    const duplicate_migrated_ping = (try client.pollProtectedShortDatagramWithInstalledKeys(3 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(duplicate_migrated_ping);
    const duplicate_ping_result = try lifecycle.feedDatagramWithInstalledKeysAndUpdatePathOrClose(
        188,
        &server,
        new_path,
        4,
        duplicate_migrated_ping,
        options,
    );
    try std.testing.expect(!duplicate_ping_result.path_challenge_queued);
    try std.testing.expect(duplicate_ping_result.selected_output_path == null);
    try std.testing.expectEqual(@as(usize, 0), server.pendingPathChallengeCount());
    try std.testing.expectEqual(@as(usize, 1), server.outstandingPathChallengeCount());

    try client.processProtectedShortDatagramWithInstalledKeys(5 * ms, client_dcid.len, challenge_packet.datagram);

    const response = (try client.pollProtectedShortDatagramWithInstalledKeys(6 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(response);
    const validation_result = try lifecycle.feedDatagramWithInstalledKeysAndUpdatePathOrCloseAndPollDatagram(
        188,
        &server,
        new_path,
        7,
        response,
        options,
        .{
            .space = .application,
            .destination_connection_id = &client_dcid,
        },
    );
    const response_route = switch (validation_result.feed.feed) {
        .routed => |route| route,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(response_route.path_changed);
    const updated_route = validation_result.feed.updated_route orelse return error.TestUnexpectedResult;
    try std.testing.expect(!validation_result.feed.path_challenge_queued);
    try std.testing.expect((validation_result.feed.selected_output_path orelse return error.TestUnexpectedResult).eql(new_path));
    try std.testing.expect((validation_result.output_path orelse return error.TestUnexpectedResult).eql(new_path));
    const ack_packet = validation_result.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ack_packet.datagram);
    try std.testing.expectEqual(@as(u64, 188), ack_packet.connection_id);
    try std.testing.expectEqual(@as(?EndpointConnectionDeadline, null), validation_result.next_deadline);
    try std.testing.expectEqual(@as(u64, 188), updated_route.connection_id);
    try std.testing.expect(!updated_route.path_changed);
    try std.testing.expectEqual(@as(usize, 0), server.outstandingPathChallengeCount());
    try std.testing.expect(!(try lifecycle.routeDatagram(new_path, response)).path_changed);
}

test "EndpointConnectionLifecycle installed-key path update OrClose queues close without route update" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    const old_path = endpoint.Udp4Tuple{
        .local = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433),
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000),
    };
    const new_path = endpoint.Udp4Tuple{
        .local = old_path.local,
        .remote = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_001),
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();
    try lifecycle.registerConnectionId(89, &server_dcid, old_path, .{});

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();
    try server.confirmHandshake();
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    // 先发 PATH_CHALLENGE 让 outstanding=1，验证 close 时 outstanding 不被消耗。
    const challenge_data = [_]u8{ 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb };
    try server.sendPathChallenge(challenge_data);
