test "EndpointConnectionLifecycle routes long datagram then drives backend and drains output" {
    const Backend = struct {
        outbound: []const u8,
        sent: bool = false,
        received: [64]u8 = undefined,
        received_len: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(context: *anyopaque, space: PacketNumberSpace, data: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake) return error.InvalidPacket;
            if (self.received_len + data.len > self.received.len) return error.BufferTooSmall;
            @memcpy(self.received[self.received_len..][0..data.len], data);
            self.received_len += data.len;
        }

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake or self.sent) return null;
            if (out_buf.len < self.outbound.len) return error.BufferTooSmall;
            @memcpy(out_buf[0..self.outbound.len], self.outbound);
            self.sent = true;
            return out_buf[0..self.outbound.len];
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x15, 0x25, 0x35, 0x45 };
    const server_dcid = [_]u8{ 0xa5, 0xb5, 0xc5, 0xd5 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try client.installHandshakeTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();
    try server.installHandshakeTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    const client_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_015);
    const server_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433);
    const server_receive_path = endpoint.Udp4Tuple{
        .local = server_addr,
        .remote = client_addr,
    };
    const server_connection_id: u64 = 74;
    try lifecycle.registerConnectionId(server_connection_id, &server_dcid, server_receive_path, .{
        .sequence_number = 0,
    });

    try client.sendCryptoInSpace(.handshake, "routed backend input");
    const client_datagram = (try client.pollProtectedLongCryptoDatagramInSpace(
        .handshake,
        10,
        &server_dcid,
        &client_dcid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(client_datagram);

    var backend = Backend{ .outbound = "routed backend response" };
    var scratch: [96]u8 = undefined;
    var drained: [1]EndpointPolledDatagramResult = undefined;
    try std.testing.expectError(
        error.InvalidPacket,
        lifecycle.processRoutedProtectedLongDatagramInSpaceAndDriveCryptoBackendAndDrainDatagrams(
            server_connection_id + 1,
            &server,
            .handshake,
            server_receive_path,
            11,
            secrets.client,
            client_datagram,
            backend.backend(),
            &scratch,
            &client_dcid,
            &server_dcid,
            &[_]u8{},
            secrets.server,
            &drained,
        ),
    );
    try std.testing.expect(!backend.sent);
    try std.testing.expectEqual(@as(usize, 0), backend.received_len);

    const result = try lifecycle.processRoutedProtectedLongDatagramInSpaceAndDriveCryptoBackendAndDrainDatagrams(
        server_connection_id,
        &server,
        .handshake,
        server_receive_path,
        11,
        secrets.client,
        client_datagram,
        backend.backend(),
        &scratch,
        &client_dcid,
        &server_dcid,
        &[_]u8{},
        secrets.server,
        &drained,
    );
    defer for (drained[0..result.backend.drain.datagrams_written]) |entry| {
        std.testing.allocator.free(entry.datagram);
    };

    try std.testing.expectEqual(server_connection_id, result.route.connection_id);
    try std.testing.expectEqualSlices(u8, &server_dcid, result.route.destination_connection_id.asSlice());
    try std.testing.expectEqualStrings("routed backend input", backend.received[0..backend.received_len]);
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.inbound_chunks);
    try std.testing.expectEqual(@as(usize, "routed backend input".len), result.backend.backend.inbound_bytes);
    try std.testing.expectEqual(@as(usize, 1), result.backend.backend.outbound_chunks);
    try std.testing.expectEqual(@as(usize, "routed backend response".len), result.backend.backend.outbound_bytes);
    try std.testing.expectEqual(@as(usize, 1), result.backend.drain.datagrams_written);
    try std.testing.expectEqual(@as(?Error, null), result.backend.drain.first_error);
    try std.testing.expectEqual(server_connection_id, drained[0].connection_id);

    try client.processProtectedLongDatagramInSpace(.handshake, 12, secrets.server, drained[0].datagram);
    var response_crypto: [64]u8 = undefined;
    const response_len = (try client.recvCryptoInSpace(.handshake, &response_crypto)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("routed backend response", response_crypto[0..response_len]);
}

test "EndpointConnectionLifecycle routed long backend OrClose drains close output" {
    const BadBackend = struct {
        peer_sent: bool = false,
        output_pulled: bool = false,
        received: [64]u8 = undefined,
        received_len: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
                .pull_peer_transport_parameters = pullPeerTransportParameters,
            };
        }

        fn receive(context: *anyopaque, space: PacketNumberSpace, data: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake) return error.InvalidPacket;
            if (self.received_len + data.len > self.received.len) return error.BufferTooSmall;
            @memcpy(self.received[self.received_len..][0..data.len], data);
            self.received_len += data.len;
        }

        fn pull(context: *anyopaque, _: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.output_pulled = true;
            if (out_buf.len == 0) return error.BufferTooSmall;
            out_buf[0] = 0;
            return out_buf[0..1];
        }

        fn pullPeerTransportParameters(context: *anyopaque, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (self.peer_sent) return null;
            if (out_buf.len == 0) return error.BufferTooSmall;
            out_buf[0] = 0x04;
            self.peer_sent = true;
            return out_buf[0..1];
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x16, 0x26, 0x36, 0x46 };
    const server_dcid = [_]u8{ 0xa6, 0xb6, 0xc6, 0xd6 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try client.installHandshakeTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();
    try server.installHandshakeTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    const client_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_016);
    const server_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433);
    const server_receive_path = endpoint.Udp4Tuple{
        .local = server_addr,
        .remote = client_addr,
    };
    const server_connection_id: u64 = 75;
    try lifecycle.registerConnectionId(server_connection_id, &server_dcid, server_receive_path, .{
        .sequence_number = 0,
    });

    try client.sendCryptoInSpace(.handshake, "routed bad backend input");
    const client_datagram = (try client.pollProtectedLongCryptoDatagramInSpace(
        .handshake,
        10,
        &server_dcid,
        &client_dcid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(client_datagram);

    var backend = BadBackend{};
    var scratch: [96]u8 = undefined;
    var drained: [1]EndpointPolledDatagramResult = undefined;
    const _routed1003 = try lifecycle.routeDatagram(server_receive_path, client_datagram);
    if (_routed1003.connection_id != server_connection_id) return error.InvalidPacket;
    const result = .{
        .route = _routed1003,
        .backend = try lifecycle.processProtectedLongDatagramInSpaceAndDriveCryptoBackendOrCloseAndDrainDatagrams(
            server_connection_id,
            &server,
            .handshake,
            11,
            secrets.client,
            client_datagram,
            backend.backend(),
            &scratch,
            &client_dcid,
            &server_dcid,
            &[_]u8{},
            secrets.server,
            &drained,
        ),
    };

    defer for (drained[0..result.backend.drain.datagrams_written]) |entry| {
        std.testing.allocator.free(entry.datagram);
    };
    try std.testing.expectEqual(server_connection_id, result.route.connection_id);
    try std.testing.expectEqualStrings("routed bad backend input", backend.received[0..backend.received_len]);
    try std.testing.expect(backend.peer_sent);
    try std.testing.expect(!backend.output_pulled);
    try std.testing.expectEqual(ConnectionState.closing, server.connectionState());
    try std.testing.expect(server.pending_close != null);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(usize, 0), result.backend.backend.inbound_chunks);
    try std.testing.expectEqual(@as(usize, 1), result.backend.drain.datagrams_written);
    try std.testing.expectEqual(@as(?Error, null), result.backend.drain.first_error);

    try std.testing.expectEqual(@as(usize, 1), try client.processProtectedLongDatagram(13, .{ .handshake = secrets.server }, drained[0].datagram));
    try std.testing.expectEqual(ConnectionState.draining, client.connectionState());
    switch (client.peerClose() orelse return error.TestUnexpectedResult) {
        .connection => |close| {
            try std.testing.expectEqual(transport_error.codeValue(.transport_parameter_error), close.error_code);
            try std.testing.expectEqual(@as(u64, @backingInt(frame.FrameType.crypto)), close.frame_type);
            try std.testing.expectEqualStrings("transport parameters", close.reason_phrase);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "EndpointConnectionLifecycle refreshes caller-keyed zero RTT timer lifecycle" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const server_scid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client_lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer client_lifecycle.deinit();
    var server_lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer server_lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_rtt_ns = 100000000,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();

    const client_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 50_000);
    const server_addr = endpoint.Udp4Address.init(.{ 127, 0, 0, 1 }, 4433);
    const server_receive_path = endpoint.Udp4Tuple{
        .local = server_addr,
        .remote = client_addr,
    };
    const client_receive_path = endpoint.Udp4Tuple{
        .local = client_addr,
        .remote = server_addr,
    };
    const client_connection_id: u64 = 10;
    const server_connection_id: u64 = 20;

    try client_lifecycle.registerConnectionId(client_connection_id, &client_scid, client_receive_path, .{
        .sequence_number = 0,
    });
    try server_lifecycle.registerConnectionId(server_connection_id, &server_scid, server_receive_path, .{
        .sequence_number = 0,
    });

    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "direct early", true);
    const early = (try client_lifecycle.pollProtectedZeroRttDatagram(
        client_connection_id,
        &client,
        10 * ms,
        &server_scid,
        &client_scid,
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(early);
    try std.testing.expectEqual(@as(usize, 1), client_lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(usize, 1), client.sentPacketCount(.application));

    try std.testing.expectError(error.InvalidPacket, server_lifecycle.processRoutedProtectedZeroRttDatagram(
        client_connection_id,
        &server,
        server_receive_path,
        11,
        secrets.client,
        early,
    ));
    const server_route = try server_lifecycle.processRoutedProtectedZeroRttDatagram(
        server_connection_id,
        &server,
        server_receive_path,
        11,
        secrets.client,
        early,
    );
    try std.testing.expectEqual(server_connection_id, server_route.connection_id);
    try std.testing.expectEqualSlices(u8, &server_scid, server_route.destination_connection_id.asSlice());
    try std.testing.expectEqual(@as(?u64, 0), server.pendingAckLargest(.application));
    try std.testing.expectEqual(@as(usize, 0), server_lifecycle.recoveryTimerCount());

    var recv_buf: [16]u8 = undefined;
    const recv_len = (try server.recvOnStream(stream_id, &recv_buf)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("direct early", recv_buf[0..recv_len]);

    const ack = (try server_lifecycle.pollProtectedShortDatagram(
        server_connection_id,
        &server,
        12 * ms,
        &client_scid,
        secrets.server,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ack);
    try std.testing.expectEqual(@as(?u64, null), server.pendingAckLargest(.application));
    try std.testing.expectEqual(@as(usize, 1), server_lifecycle.recoveryTimerCount());

    const client_route = try client_lifecycle.routeDatagram(client_receive_path, ack);
    try std.testing.expectEqual(client_connection_id, client_route.connection_id);
    try client_lifecycle.processProtectedShortDatagram(
        client_route.connection_id,
        &client,
        13,
        secrets.server,
        client_scid.len,
        ack,
    );
    try std.testing.expectEqual(@as(usize, 0), client.sentPacketCount(.application));
    try std.testing.expectEqual(@as(usize, 0), client.bytesInFlight(.application));
    try std.testing.expectEqual(@as(usize, 0), client_lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?u64, 0), client.pendingAckLargest(.application));

    const final_ack = (try client_lifecycle.pollProtectedShortDatagram(
        client_connection_id,
        &client,
        14 * ms,
        &server_scid,
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(final_ack);
    try std.testing.expectEqual(@as(?u64, null), client.pendingAckLargest(.application));
    try std.testing.expectEqual(@as(usize, 0), client_lifecycle.recoveryTimerCount());

    const server_ack_route = try server_lifecycle.routeDatagram(server_receive_path, final_ack);
    try std.testing.expectEqual(server_connection_id, server_ack_route.connection_id);
    try server_lifecycle.processProtectedShortDatagram(
        server_ack_route.connection_id,
        &server,
        15,
        secrets.client,
        server_scid.len,
        final_ack,
    );
    try std.testing.expectEqual(@as(usize, 0), server.bytesInFlight(.application));
    try std.testing.expectEqual(@as(usize, 0), server_lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), server_lifecycle.earliestRecoveryDeadline());
}

