    defer std.testing.allocator.free(request);

    var backend = Backend{
        .peer_transport_parameters = peer_params_out.getWritten(),
        .outbound = "routed compatible drain response",
    };
    var scratch: [256]u8 = undefined;
    var out: [1]EndpointPolledDatagramResult = undefined;
    const poll_options: EndpointPollInstalledKeyDatagramOptions = .{
        .space = .application,
        .destination_connection_id = &client_dcid,
    };
    try std.testing.expectError(error.InvalidPacket, server_lifecycle.routeAndVerifyDatagram(client_connection_id, server_receive_path, request));
    try std.testing.expectEqual(@as(usize, 0), backend.receive_calls);
    try std.testing.expect(!backend.peer_sent);
    try std.testing.expectEqual(@as(?u64, null), server.pendingAckLargest(.application));

    const _routed1067 = try server_lifecycle.routeDatagram(server_receive_path, request);
    if (_routed1067.connection_id != server_connection_id) return error.InvalidPacket;
    const result = .{
        .route = _routed1067,
        .backend = try server_lifecycle.processProtectedShortDatagramWithInstalledKeysAndDriveCryptoBackendInSpaceWithCompatibleVersionAndDrainDatagrams(
            server_connection_id,
            &server,
            11,
            _routed1067.destination_connection_id.asSlice().len,
            request,
            .application,
            backend.backend(),
            &scratch,
            &compatibilities,
            12,
            poll_options,
            &out,
        ),
