    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();

    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    try client.sendCryptoInSpace(.application, "client app poll");
    const request = (try client_lifecycle.pollProtectedShortDatagramWithInstalledKeys(
        57,
        &client,
        10,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(request);

    var backend = Backend{ .outbound = "server app poll" };
    var scratch: [64]u8 = undefined;
    const result = try server_lifecycle.processProtectedShortDatagramWithInstalledKeysAndDriveCryptoBackendInSpaceAndPollDatagram(
        67,
        &server,
        11,
        server_dcid.len,
        request,
        .application,
        backend.backend(),
        &scratch,
        12,
        .{
            .space = .application,
            .destination_connection_id = &client_dcid,
        },
    );
    try std.testing.expectEqual(@as(usize, 1), result.backend.connections_driven);
    try std.testing.expectEqual(@as(usize, 1), result.backend.progress.inbound_chunks);
    try std.testing.expectEqual(@as(usize, "client app poll".len), result.backend.progress.inbound_bytes);
    try std.testing.expectEqual(@as(usize, 1), result.backend.progress.outbound_chunks);
    try std.testing.expectEqualStrings("client app poll", backend.received[0..backend.received_len]);
    try std.testing.expect(backend.outbound_sent);
    const response = result.datagram orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 67), response.connection_id);
    defer std.testing.allocator.free(response.datagram);
    try std.testing.expectEqual(@as(?u64, null), server.pendingAckLargest(.application));

    try client_lifecycle.processProtectedShortDatagramWithInstalledKeys(
        57,
        &client,
        13,
        client_dcid.len,
        response.datagram,
    );
    var recv_buf: [64]u8 = undefined;
    const recv_len = (try client.recvCryptoInSpace(.application, &recv_buf)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("server app poll", recv_buf[0..recv_len]);
}

