test "EndpointConnectionLifecycle drives crypto backend across ordered spaces in one call" {
    const FlightBackend = struct {
        initial_inbound: std.ArrayList(u8) = .empty,
        initial_outbound: []const u8,
        initial_offset: usize = 0,
        handshake_outbound: []const u8,
        handshake_offset: usize = 0,
        secrets: HandshakeTrafficSecrets,
        secrets_sent: bool = false,

        fn deinit(self: *@This()) void {
            self.initial_inbound.deinit(std.testing.allocator);
        }

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
                .pull_handshake_traffic_secrets = pullHandshakeTrafficSecrets,
            };
        }

        fn receive(context: *anyopaque, space: PacketNumberSpace, data: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .initial) return error.Internal;
            self.initial_inbound.appendSlice(std.testing.allocator, data) catch return error.OutOfMemory;
        }

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            switch (space) {
                .initial => {
                    if (self.initial_offset >= self.initial_outbound.len) return null;
                    const n = @min(out_buf.len, self.initial_outbound.len - self.initial_offset);
                    @memcpy(out_buf[0..n], self.initial_outbound[self.initial_offset..][0..n]);
                    self.initial_offset += n;
                    return out_buf[0..n];
                },
                .handshake => {
                    if (self.handshake_offset >= self.handshake_outbound.len) return null;
                    const n = @min(out_buf.len, self.handshake_outbound.len - self.handshake_offset);
                    @memcpy(out_buf[0..n], self.handshake_outbound[self.handshake_offset..][0..n]);
                    self.handshake_offset += n;
                    return out_buf[0..n];
                },
                else => return null,
            }
        }

        fn pullHandshakeTrafficSecrets(context: *anyopaque) Error!?HandshakeTrafficSecrets {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (self.secrets_sent) return null;
            self.secrets_sent = true;
            return self.secrets;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_rtt_ns = 100000000,
    });
    defer server.deinit();
    try server.validatePeerAddress();

    var request: [64]u8 = undefined;
    var out = buffer.fixedWriter(&request);
    try frame.encodeFrame(out.writer(), .{ .crypto = .{
        .offset = 0,
        .data = "client hello",
    } });
    try server.processDatagramInSpace(.initial, 0, out.getWritten());

    var backend = FlightBackend{
        .initial_outbound = "server hello",
        .handshake_outbound = "encrypted extensions",
        .secrets = .{
            .local = @as([protection.traffic_secret_len]u8, @splat(0x33)),
            .peer = @as([protection.traffic_secret_len]u8, @splat(0x44)),
        },
    };
    defer backend.deinit();

    var scratch: [8]u8 = undefined;
    const spaces = [_]PacketNumberSpace{ .initial, .handshake };
    const progress = try lifecycle.driveCryptoBackendAcrossSpacesAndArmConnection(
        73,
        &server,
        &spaces,
        backend.backend(),
        &scratch,
    );

    try std.testing.expectEqualStrings("client hello", backend.initial_inbound.items);
    try std.testing.expect(progress.handshake_keys_installed);
    try std.testing.expect(server.hasHandshakeProtectionKeys());
    try std.testing.expectEqual(
        backend.initial_outbound.len + backend.handshake_outbound.len,
        progress.outbound_bytes,
    );
    try std.testing.expect(!server.packetNumberSpaceDiscarded(.handshake));
    try std.testing.expect(server.sentPacketCount(.initial) == 0);

    var initial_crypto: [64]u8 = undefined;
    var initial_len: usize = 0;
    for (server.initial_packet_space.crypto_send_queue.items) |pending| {
        @memcpy(initial_crypto[initial_len..][0..pending.data.len], pending.data);
        initial_len += pending.data.len;
    }
    try std.testing.expectEqualStrings("server hello", initial_crypto[0..initial_len]);

    var handshake_crypto: [64]u8 = undefined;
    var handshake_len: usize = 0;
    for (server.handshake_packet_space.crypto_send_queue.items) |pending| {
        @memcpy(handshake_crypto[handshake_len..][0..pending.data.len], pending.data);
        handshake_len += pending.data.len;
    }
    try std.testing.expectEqualStrings("encrypted extensions", handshake_crypto[0..handshake_len]);
}

test "EndpointConnectionLifecycle drives backends across ordered spaces for multiple connections" {
    const FlightBackend = struct {
        initial_inbound: std.ArrayList(u8) = .empty,
        initial_outbound: []const u8,
        initial_offset: usize = 0,
        handshake_outbound: []const u8,
        handshake_offset: usize = 0,
        secrets: HandshakeTrafficSecrets,
        secrets_sent: bool = false,

        fn deinit(self: *@This()) void {
            self.initial_inbound.deinit(std.testing.allocator);
        }

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
                .pull_handshake_traffic_secrets = pullHandshakeTrafficSecrets,
            };
        }

        fn receive(context: *anyopaque, space: PacketNumberSpace, data: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .initial) return error.Internal;
            self.initial_inbound.appendSlice(std.testing.allocator, data) catch return error.OutOfMemory;
        }

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            switch (space) {
                .initial => {
                    if (self.initial_offset >= self.initial_outbound.len) return null;
                    const n = @min(out_buf.len, self.initial_outbound.len - self.initial_offset);
                    @memcpy(out_buf[0..n], self.initial_outbound[self.initial_offset..][0..n]);
                    self.initial_offset += n;
                    return out_buf[0..n];
                },
                .handshake => {
                    if (self.handshake_offset >= self.handshake_outbound.len) return null;
                    const n = @min(out_buf.len, self.handshake_outbound.len - self.handshake_offset);
                    @memcpy(out_buf[0..n], self.handshake_outbound[self.handshake_offset..][0..n]);
                    self.handshake_offset += n;
                    return out_buf[0..n];
                },
                else => return null,
            }
        }

        fn pullHandshakeTrafficSecrets(context: *anyopaque) Error!?HandshakeTrafficSecrets {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (self.secrets_sent) return null;
            self.secrets_sent = true;
            return self.secrets;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var first = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer first.deinit();
    try first.validatePeerAddress();
    var second = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer second.deinit();
    try second.validatePeerAddress();

    inline for (.{ &first, &second }) |conn| {
        var request: [64]u8 = undefined;
        var out = buffer.fixedWriter(&request);
        try frame.encodeFrame(out.writer(), .{ .crypto = .{
            .offset = 0,
            .data = "client hello",
        } });
        try conn.processDatagramInSpace(.initial, 0, out.getWritten());
    }

    var first_backend = FlightBackend{
        .initial_outbound = "server hello",
        .handshake_outbound = "encrypted extensions",
        .secrets = .{
            .local = @as([protection.traffic_secret_len]u8, @splat(0x51)),
            .peer = @as([protection.traffic_secret_len]u8, @splat(0x52)),
        },
    };
    defer first_backend.deinit();
    var second_backend = FlightBackend{
        .initial_outbound = "server hi",
        .handshake_outbound = "cert",
        .secrets = .{
            .local = @as([protection.traffic_secret_len]u8, @splat(0x61)),
            .peer = @as([protection.traffic_secret_len]u8, @splat(0x62)),
        },
    };
    defer second_backend.deinit();

    var first_scratch: [8]u8 = undefined;
    var second_scratch: [8]u8 = undefined;
    const views = [_]EndpointCryptoBackendDriveView{
        .{ .connection_id = 81, .connection = &first, .backend = first_backend.backend(), .scratch = &first_scratch },
        .{ .connection_id = 82, .connection = &second, .backend = second_backend.backend(), .scratch = &second_scratch },
    };
    const spaces = [_]PacketNumberSpace{ .initial, .handshake };
    const sweep = try lifecycle.driveCryptoBackendsAcrossSpacesAndArmConnections(&spaces, &views);

    try std.testing.expectEqual(@as(usize, 2), sweep.connections_driven);
    try std.testing.expect(sweep.progress.handshake_keys_installed);
    try std.testing.expectEqual(
        first_backend.initial_outbound.len + first_backend.handshake_outbound.len +
            second_backend.initial_outbound.len + second_backend.handshake_outbound.len,
        sweep.progress.outbound_bytes,
    );
    try std.testing.expect(first.hasHandshakeProtectionKeys());
    try std.testing.expect(second.hasHandshakeProtectionKeys());
    try std.testing.expectEqualStrings("client hello", first_backend.initial_inbound.items);
    try std.testing.expectEqualStrings("client hello", second_backend.initial_inbound.items);
    try std.testing.expect(first.initial_packet_space.crypto_send_queue.items.len > 0);
    try std.testing.expect(first.handshake_packet_space.crypto_send_queue.items.len > 0);
    try std.testing.expect(second.initial_packet_space.crypto_send_queue.items.len > 0);
    try std.testing.expect(second.handshake_packet_space.crypto_send_queue.items.len > 0);
}

test "EndpointConnectionLifecycle refreshes recovery timer after strict backend drive rejects closing connection" {
    const TrackingBackend = struct {
        receive_count: usize = 0,
        pull_count: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(context: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.receive_count += 1;
        }

        fn pull(context: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pull_count += 1;
            return null;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var conn = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer conn.deinit();
    try conn.confirmHandshake();
    _ = try conn.recordPacketSentInSpace(.application, 10 * ms, 100);
    try lifecycle.armRecoveryTimerFromConnection(52, &conn);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());
    try std.testing.expect(lifecycle.earliestRecoveryDeadline() != null);

    try conn.closeConnection(0, @backingInt(frame.FrameType.crypto), "done");
    try std.testing.expectEqual(@as(?LossDetectionTimerDeadline, null), conn.lossDetectionTimerDeadline());

    var backend = TrackingBackend{};
    var scratch: [16]u8 = undefined;
    try std.testing.expectError(
        error.ConnectionClosed,
        lifecycle.driveCryptoBackendInSpaceAndArmConnection(
            52,
            &conn,
            .handshake,
            backend.backend(),
            &scratch,
        ),
    );
    try std.testing.expectEqual(@as(usize, 0), backend.receive_count);
    try std.testing.expectEqual(@as(usize, 0), backend.pull_count);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());
}

test "EndpointConnectionLifecycle refreshes recovery timer after compatible backend drive rejects closing connection" {
    const TrackingBackend = struct {
        receive_count: usize = 0,
        pull_count: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(context: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.receive_count += 1;
        }

        fn pull(context: *anyopaque, _: PacketNumberSpace, _: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.pull_count += 1;
            return null;
        }
    };

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var conn = try Connection.init(std.testing.allocator, .server, .{
        .initial_rtt_ns = 100000000,
    });
    defer conn.deinit();
    try conn.validatePeerAddress();
    try conn.confirmHandshake();
    _ = try conn.recordPacketSentInSpace(.application, 10 * ms, 100);
    try lifecycle.armRecoveryTimerFromConnection(53, &conn);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    try conn.closeConnection(0, @backingInt(frame.FrameType.crypto), "done");
    try std.testing.expectEqual(@as(?LossDetectionTimerDeadline, null), conn.lossDetectionTimerDeadline());

    var backend = TrackingBackend{};
    var scratch: [16]u8 = undefined;
    const compatibilities = [_]VersionCompatibility{.{
        .original_version = .v1,
        .negotiated_version = .v1,
    }};
    try std.testing.expectError(
        error.ConnectionClosed,
        lifecycle.driveCryptoBackendInSpaceWithCompatibleVersionAndArmConnection(
            53,
            &conn,
            .handshake,
            backend.backend(),
            &scratch,
            &compatibilities,
        ),
    );
    try std.testing.expectEqual(@as(usize, 0), backend.receive_count);
    try std.testing.expectEqual(@as(usize, 0), backend.pull_count);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());
}

test "EndpointConnectionLifecycle backend poll returns caller-keyed long next deadline" {
    const Backend = struct {
        outbound: []const u8,
        sent: bool = false,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(_: *anyopaque, _: PacketNumberSpace, _: []const u8) Error!void {}

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake or self.sent) return null;
            if (out_buf.len < self.outbound.len) return error.BufferTooSmall;
            @memcpy(out_buf[0..self.outbound.len], self.outbound);
            self.sent = true;
            return out_buf[0..self.outbound.len];
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();
    try server.installHandshakeTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var backend = Backend{ .outbound = "server keyed poll" };
    var scratch: [64]u8 = undefined;
    const result = try lifecycle.driveCryptoBackendInSpaceAndPollProtectedLongCryptoDatagram(
        61,
        &server,
        .handshake,
        backend.backend(),
        &scratch,
        .handshake,
        10,
        &client_dcid,
        &server_dcid,
        &[_]u8{},
        secrets.server,
    );
    defer if (result.datagram) |datagram| std.testing.allocator.free(datagram.datagram);

    try std.testing.expectEqual(@as(usize, 1), result.backend.outbound_chunks);
    try std.testing.expect(result.datagram != null);
    const next_deadline = result.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 61), next_deadline.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, next_deadline.kind);
    try std.testing.expectEqual(PacketNumberSpace.handshake, next_deadline.recovery.?.space);
}

test "EndpointConnectionLifecycle drives backend and drains caller-keyed long crypto datagrams" {
    const Backend = struct {
        outbound: []const []const u8,
        outbound_index: usize = 0,
        received: [128]u8 = undefined,
        received_len: usize = 0,

        fn backend(self: *@This()) CryptoBackend {
            return .{
                .context = self,
                .receive = receive,
                .pull = pull,
            };
        }

        fn receive(context: *anyopaque, space: PacketNumberSpace, data: []const u8) Error!void {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake) return error.InvalidPacket;
            if (self.received_len + data.len > self.received.len) return error.BufferTooSmall;
            @memcpy(self.received[self.received_len..][0..data.len], data);
            self.received_len += data.len;
        }

        fn pull(context: *anyopaque, space: PacketNumberSpace, out_buf: []u8) Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (space != .handshake or self.outbound_index >= self.outbound.len) return null;
            const outbound = self.outbound[self.outbound_index];
            if (out_buf.len < outbound.len) return error.BufferTooSmall;
            @memcpy(out_buf[0..outbound.len], outbound);
            self.outbound_index += 1;
            return out_buf[0..outbound.len];
        }
    };

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const outbound = [_][]const u8{
        "server keyed drain one",
        "server keyed drain two",
    };

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try client.installHandshakeTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();
    try server.installHandshakeTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    try client.sendCryptoInSpace(.handshake, "client keyed drain input");
    const client_datagram = (try lifecycle.pollProtectedLongCryptoDatagramInSpace(
        61,
        &client,
        .handshake,
        10 * ms,
        &server_dcid,
        &client_dcid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(client_datagram);

    try lifecycle.processProtectedLongDatagramInSpace(
        62,
        &server,
        .handshake,
        11,
        secrets.client,
        client_datagram,
    );

    var backend = Backend{ .outbound = &outbound };
    var scratch: [128]u8 = undefined;
    var first_out: [1]EndpointPolledDatagramResult = undefined;
    const result = try lifecycle.driveCryptoBackendInSpaceAndDrainProtectedLongCryptoDatagrams(
        62,
        &server,
        .handshake,
        backend.backend(),
        &scratch,
        .handshake,
        12,
        &client_dcid,
        &server_dcid,
        &[_]u8{},
        secrets.server,
        &first_out,
    );
    defer for (first_out[0..result.drain.datagrams_written]) |entry| {
        std.testing.allocator.free(entry.datagram);
    };

    try std.testing.expectEqualStrings("client keyed drain input", backend.received[0..backend.received_len]);
    try std.testing.expectEqual(@as(usize, 1), result.backend.inbound_chunks);
    try std.testing.expectEqual(@as(usize, "client keyed drain input".len), result.backend.inbound_bytes);
    try std.testing.expectEqual(@as(usize, 2), result.backend.outbound_chunks);
    try std.testing.expectEqual(@as(usize, outbound[0].len + outbound[1].len), result.backend.outbound_bytes);
    try std.testing.expectEqual(@as(usize, 1), result.drain.datagrams_written);
    try std.testing.expectEqual(@as(?Error, null), result.drain.first_error);
    try std.testing.expectEqual(@as(u64, 62), first_out[0].connection_id);
    const next_deadline = result.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 62), next_deadline.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.recovery, next_deadline.kind);
    try std.testing.expectEqual(PacketNumberSpace.handshake, next_deadline.recovery.?.space);

    var rest_out: [4]EndpointPolledDatagramResult = undefined;
    const rest = lifecycle.drainProtectedLongCryptoDatagramsInSpace(
        62,
        &server,
        .handshake,
        13,
        &client_dcid,
        &server_dcid,
        &[_]u8{},
        secrets.server,
        &rest_out,
    );
    defer for (rest_out[0..rest.datagrams_written]) |entry| {
        std.testing.allocator.free(entry.datagram);
    };
    try std.testing.expectEqual(@as(usize, 1), rest.datagrams_written);
    try std.testing.expectEqual(@as(?Error, null), rest.first_error);

    try client.processProtectedLongDatagramInSpace(.handshake, 14, secrets.server, first_out[0].datagram);
    try client.processProtectedLongDatagramInSpace(.handshake, 15, secrets.server, rest_out[0].datagram);
    var response_crypto: [64]u8 = undefined;
    const response_len = (try client.recvCryptoInSpace(.handshake, &response_crypto)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(
        "server keyed drain oneserver keyed drain two",
        response_crypto[0..response_len],
    );
}

