    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());

    const close_packet = (try lifecycle.pollProtectedShortDatagram(
        56,
        &server,
        13 * ms,
        &client_dcid,
        secrets.server,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(close_packet);

    try client.processProtectedShortDatagram(14 * ms, secrets.server, client_dcid.len, close_packet);
    try std.testing.expectEqual(ConnectionState.draining, client.connectionState());
    switch (client.peerClose() orelse return error.TestUnexpectedResult) {
        .connection => |close| {
            try std.testing.expectEqual(transport_error.codeValue(.frame_encoding_error), close.error_code);
            try std.testing.expectEqual(@as(u64, 0x1f), close.frame_type);
            try std.testing.expectEqualStrings("frame encoding", close.reason_phrase);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "EndpointConnectionLifecycle refreshes installed-key protected short OrClose error state" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_rtt_ns = 100000000,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try server.confirmHandshake();
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer client.deinit();
    try client.confirmHandshake();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });

    try server.sendPing();
    const server_ping = (try lifecycle.pollProtectedShortDatagramWithInstalledKeys(
        57,
        &server,
        10,
        &client_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(server_ping);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());
    try std.testing.expect(lifecycle.earliestRecoveryDeadline() != null);
    try client.processProtectedShortDatagramWithInstalledKeys(11 * ms, client_dcid.len, server_ping);

    const client_keys = protection.deriveAes128PacketProtectionKeys(secrets.client.secret);
    const unknown_frame = [_]u8{ 0x1f, 0, 0, 0 };
    const invalid_short = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 0,
    }, try packet.encodePacketNumberForHeader(0, null), client_keys, &unknown_frame);
    defer std.testing.allocator.free(invalid_short);

    try std.testing.expectError(
        error.InvalidPacket,
        lifecycle.processProtectedShortDatagramWithInstalledKeysOrClose(
            57,
            &server,
            12,
            server_dcid.len,
            invalid_short,
        ),
    );
    try std.testing.expectEqual(ConnectionState.closing, server.connectionState());
    try std.testing.expect(server.pending_close != null);
    try std.testing.expectEqual(@as(usize, 0), lifecycle.recoveryTimerCount());
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), lifecycle.earliestRecoveryDeadline());

    const close_packet = (try lifecycle.pollProtectedShortDatagramWithInstalledKeys(
        57,
        &server,
        13,
        &client_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(close_packet);

    try client.processProtectedShortDatagramWithInstalledKeys(14 * ms, client_dcid.len, close_packet);
    try std.testing.expectEqual(ConnectionState.draining, client.connectionState());
    switch (client.peerClose() orelse return error.TestUnexpectedResult) {
        .connection => |close| {
            try std.testing.expectEqual(transport_error.codeValue(.frame_encoding_error), close.error_code);
            try std.testing.expectEqual(@as(u64, 0x1f), close.frame_type);
            try std.testing.expectEqualStrings("frame encoding", close.reason_phrase);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "EndpointConnectionLifecycle services and polls protected long Handshake PTO probe" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100000000,
    });
    defer client.deinit();

    _ = try client.recordPacketSentInSpace(.initial, 10 * ms, 100);
    try client.receiveAckInSpace(.initial, 70 * ms, .{
        .largest_acknowledged = 0,
        .ack_delay = 0,
        .first_ack_range = 0,
    });
    try client.installHandshakeTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try lifecycle.armRecoveryTimerFromConnection(41, &client);

    const deadline = lifecycle.earliestRecoveryDeadline() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 41), deadline.connection_id);
    try std.testing.expectEqual(PacketNumberSpace.handshake, deadline.timer.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, deadline.timer.kind);

    const early = try lifecycle.serviceRecoveryTimerAndPollProtectedLongDatagram(
        41,
        &client,
        deadline.timer.deadline_nanos - 1,
        &server_dcid,
        &client_dcid,
        &[_]u8{},
        .{ .handshake = secrets.client },
    );
    try std.testing.expectEqual(@as(?EndpointLossDetectionTimerDeadline, null), early.serviced);
    try std.testing.expectEqual(@as(?[]u8, null), early.datagram);
    try std.testing.expectEqual(@as(usize, 0), client.handshake_packet_space.pending_ping_count);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());

    const due = try lifecycle.serviceRecoveryTimerAndPollProtectedLongDatagram(
        41,
        &client,
        deadline.timer.deadline_nanos,
        &server_dcid,
        &client_dcid,
        &[_]u8{},
        .{ .handshake = secrets.client },
    );
    const serviced = due.serviced orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 41), serviced.connection_id);
    try std.testing.expectEqual(PacketNumberSpace.handshake, serviced.timer.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, serviced.timer.kind);
    const probe = due.datagram orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(probe);
    try std.testing.expectEqual(@as(usize, 1), client.sentPacketCount(.handshake));
    try std.testing.expectEqual(@as(usize, 0), client.handshake_packet_space.pending_ping_count);
    // Sending the Handshake probe discards Initial state, which resets the
    // shared PTO backoff while preserving the newly in-flight Handshake packet.
    try std.testing.expectEqual(@as(u8, 0), client.handshake_packet_space.recovery_state.pto_count);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.recoveryTimerCount());
    try std.testing.expect(client.packetNumberSpaceDiscarded(.initial));

    var opened = try protection.unprotectLongPacketAes128(
        std.testing.allocator,
        secrets.client,
        probe,
        0,
    );
    defer protection.deinitProtectedLongPacket(&opened, std.testing.allocator);
    try std.testing.expectEqual(packet.PacketType.handshake, opened.packet.header.packet_type);

    var payload_offset: usize = 0;
    var found_ping = false;
    while (payload_offset < opened.packet.plaintext.len) {
        var decoded = try frame.decodeFrameSlice(opened.packet.plaintext[payload_offset..], std.testing.allocator);
        defer frame.deinitFrame(&decoded.frame, std.testing.allocator);
        switch (decoded.frame) {
            .ping => found_ping = true,
            .padding => {},
            else => return error.TestUnexpectedResult,
        }
        payload_offset += decoded.len;
    }
    try std.testing.expect(found_ping);
}

