    try std.testing.expectEqual(ConnectionState.closing, closing.connectionState());
    try std.testing.expectEqual(@as(u64, 0), closing.nextPeerPacketNumber(.initial));
    try std.testing.expectEqual(@as(u64, 0), closing.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, null), closing.pendingAckLargest(.initial));
    try std.testing.expectEqual(@as(?u64, null), closing.pendingAckLargest(.application));
    try std.testing.expect(closing.pending_close != null);

    var close_buf: [64]u8 = undefined;
    var close_out = buffer.fixedWriter(&close_buf);
    try frame.encodeFrame(close_out.writer(), .{ .application_close = .{
        .error_code = 0,
        .reason_phrase = "drain",
    } });

    var draining = try Connection.init(std.testing.allocator, .server, .{});
    defer draining.deinit();
    try draining.processDatagram(20 * ms, close_out.getWritten());
    try std.testing.expectEqual(ConnectionState.draining, draining.connectionState());

    try std.testing.expectEqual(@as(usize, 0), try draining.processProtectedLongDatagramOrClose(21, .{
        .initial = secrets.client,
        .zero_rtt = secrets.client,
    }, &invalid_protected));
    try draining.processProtectedZeroRttDatagramOrClose(22, secrets.client, &invalid_protected);
    try std.testing.expectEqual(ConnectionState.draining, draining.connectionState());
    try std.testing.expectEqual(@as(u64, 0), draining.nextPeerPacketNumber(.initial));
    try std.testing.expectEqual(@as(u64, 0), draining.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, null), draining.pendingAckLargest(.initial));
    try std.testing.expectEqual(@as(?u64, null), draining.pendingAckLargest(.application));
    switch (draining.peerClose() orelse return error.TestUnexpectedResult) {
        .application => |close| try std.testing.expectEqualStrings("drain", close.reason_phrase),
        else => return error.TestUnexpectedResult,
    }
}

test "protected short datagram spin bit follows enabled single-path policy" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const client_dcid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{ .enable_spin_bit = true });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{ .enable_spin_bit = true });
    defer server.deinit();
    try server.validatePeerAddress();

    try std.testing.expect(!client.nextOutgoingSpinBit());
    try client.sendPing();
    const first_client_packet = (try client.pollProtectedShortDatagram(
        10 * ms,
        &server_dcid,
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(first_client_packet);
    try std.testing.expect(!try protection.peekShortPacketSpinBit(first_client_packet));

    try server.processProtectedShortDatagram(11 * ms, secrets.client, server_dcid.len, first_client_packet);
    try std.testing.expect(!server.nextOutgoingSpinBit());
    const server_ack = (try server.pollProtectedShortDatagram(
        12 * ms,
        &client_dcid,
        secrets.server,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(server_ack);
    try std.testing.expect(!try protection.peekShortPacketSpinBit(server_ack));

    try client.processProtectedShortDatagram(13 * ms, secrets.server, client_dcid.len, server_ack);
    try std.testing.expect(client.nextOutgoingSpinBit());
    try client.sendPing();
    const second_client_packet = (try client.pollProtectedShortDatagram(
        14 * ms,
        &server_dcid,
        secrets.client,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(second_client_packet);
    try std.testing.expect(try protection.peekShortPacketSpinBit(second_client_packet));

    try server.processProtectedShortDatagram(15 * ms, secrets.client, server_dcid.len, second_client_packet);
    try std.testing.expect(server.nextOutgoingSpinBit());
    server.resetSpinBitForPath();
    try std.testing.expect(!server.nextOutgoingSpinBit());
}

