test "installed one RTT key update requires handshake confirmation and ACK before next update" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();

    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    try std.testing.expectError(error.InvalidPacket, client.initiateOneRttKeyUpdate());
    try client.confirmHandshake();
    try server.confirmHandshake();
    try std.testing.expectEqual(@as(?u64, null), client.pendingOneRttKeyUpdateAckThreshold());
    try std.testing.expectEqual(@as(?u64, 0), client.localOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?u64, 0), server.peerOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(1));
    try client.initiateOneRttKeyUpdate();
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttKeyPhase());
    try std.testing.expectEqual(@as(?u64, 1), client.localOneRttKeyUpdateCount());
    // The previous generation is retained after an advance so delayed packets
    // protected with the old key phase can still be opened (RFC 9001 §6.5).
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(1));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(2));
    try std.testing.expectEqual(@as(?u64, 0), client.pendingOneRttKeyUpdateAckThreshold());
    try std.testing.expectError(error.InvalidPacket, client.initiateOneRttKeyUpdate());

    try client.sendPing();
    const ping = (try client.pollProtectedShortDatagramWithInstalledKeys(
        10,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ping);
    try server.processProtectedShortDatagramWithInstalledKeys(11 * ms, server_dcid.len, ping);
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(1));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(2));
    const ack = (try server.pollProtectedShortDatagramWithInstalledKeys(
        12,
        &client_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ack);
    try client.processProtectedShortDatagramWithInstalledKeys(13 * ms, client_dcid.len, ack);
    try std.testing.expectEqual(@as(?u64, null), client.pendingOneRttKeyUpdateAckThreshold());

    try client.initiateOneRttKeyUpdate();
    try std.testing.expectEqual(@as(?bool, false), client.localOneRttKeyPhase());
    try std.testing.expectEqual(@as(?u64, 2), client.localOneRttKeyUpdateCount());
    // Second advance overwrites the retained previous: generation 1 is now
    // previous, generation 0 is no longer retained.
    try std.testing.expectEqual(@as(?bool, false), client.localOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(1));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(2));
    try std.testing.expectEqual(@as(?bool, true), client.localOneRttRetainsKeyGeneration(3));
    try std.testing.expectEqual(@as(?u64, 1), client.pendingOneRttKeyUpdateAckThreshold());

    try client.sendPing();
    const second_ping = (try client.pollProtectedShortDatagramWithInstalledKeys(
        14,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(second_ping);
    try server.processProtectedShortDatagramWithInstalledKeys(15 * ms, server_dcid.len, second_ping);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttKeyPhase());
    try std.testing.expectEqual(@as(?u64, 2), server.peerOneRttKeyUpdateCount());
    // Second peer advance overwrites the retained previous: generation 1 is
    // now previous, generation 0 is no longer retained.
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(1));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(2));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(3));
    const stale_generation_0_keys = secrets.client;
    const stale_ping_plaintext = [_]u8{
        @backingInt(frame.FrameType.ping),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
    };
    const stale_generation_0_ping = try protection.protectShortPacketAes128(
        std.testing.allocator,
        .{
            .dcid = &server_dcid,
            .key_phase = false,
            .packet_number = 2,
        },
        try packet.encodePacketNumberForHeader(2, null),
        stale_generation_0_keys,
        &stale_ping_plaintext,
    );
    defer std.testing.allocator.free(stale_generation_0_ping);
    try std.testing.expectError(
        error.InvalidPacket,
        server.processProtectedShortDatagramWithInstalledKeys(16 * ms, server_dcid.len, stale_generation_0_ping),
    );
    try std.testing.expectEqual(@as(u64, 2), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 1), server.pendingAckLargest(.application));
    try std.testing.expectEqual(@as(?u64, 2), server.peerOneRttKeyUpdateCount());
    const second_ack = (try server.pollProtectedShortDatagramWithInstalledKeys(
        17,
        &client_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(second_ack);
    try client.processProtectedShortDatagramWithInstalledKeys(18 * ms, client_dcid.len, second_ack);
    try std.testing.expectEqual(@as(?u64, null), client.pendingOneRttKeyUpdateAckThreshold());
}

test "key update recovers via PTO when the key-update packet is lost" {
    // RFC 9001 §6.2 under real loss: the client initiates a 1-RTT key update
    // and sends an ack-eliciting packet protected with the flipped key phase.
    // That packet is dropped, so the server never sees the update; the client
    // must recover by PTO retransmission (RFC 9002 §6.2), after which the server
    // observes the key-phase flip and the update is confirmed.
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_rtt_ns = 100 * ms,
        .enable_rtt_update = false,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();

    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });
    try client.confirmHandshake();
    try server.confirmHandshake();

    // Client initiates a 1-RTT key update and sends an ack-eliciting ping.
    try client.initiateOneRttKeyUpdate();
    try std.testing.expectEqual(@as(?u64, 1), client.localOneRttKeyUpdateCount());
    try client.sendPing();
    const ku_packet = (try client.pollProtectedShortDatagramWithInstalledKeys(10 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ku_packet);

    // The key-update packet is lost: never delivered to the server. The client
    // has an in-flight ack-eliciting packet, so the application PTO is armed.
    const deadline = client.lossDetectionTimerDeadline() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(PacketNumberSpace.application, deadline.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, deadline.kind);

    // Fire the PTO: the client re-queues a probe carrying the pending ping.
    const serviced = (try client.serviceLossDetectionTimer(deadline.deadline_nanos)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(PacketNumberSpace.application, serviced.space);
    try std.testing.expectEqual(LossDetectionTimerKind.pto, serviced.kind);

    // The retransmission carries the flipped key phase to the server.
    const retransmit = (try client.pollProtectedShortDatagramWithInstalledKeys(deadline.deadline_nanos + 1, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(retransmit);

    // Deliver the retransmission: the server sees the flip, updates its keys,
    // and ACKs.
    try server.processProtectedShortDatagramWithInstalledKeys(deadline.deadline_nanos + 2, server_dcid.len, retransmit);
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());

    const ack = (try server.pollProtectedShortDatagramWithInstalledKeys(deadline.deadline_nanos + 3, &client_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ack);
    try client.processProtectedShortDatagramWithInstalledKeys(deadline.deadline_nanos + 4, client_dcid.len, ack);
    try std.testing.expectEqual(@as(?u64, null), client.pendingOneRttKeyUpdateAckThreshold());
}

test "EndpointConnectionLifecycle wakes to discard expired retained 1 RTT keys" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const client_dcid = [_]u8{ 0x11, 0x22, 0x33, 0x44 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{ .initial_rtt_ns = 100 });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const update = (try client.pollProtectedShortDatagramWithInstalledKeys(100 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(update);
    try server.processProtectedShortDatagramWithInstalledKeys(100 * ms, server_dcid.len, update);
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    const discard_deadline = server.oneRttKeyDiscardDeadline() orelse return error.TestUnexpectedResult;
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();
    const next = lifecycle.nextDeadline(7, &server) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.key_discard, next.kind);
    try std.testing.expectEqual(discard_deadline, next.deadline_nanos);

    const due = (try lifecycle.processDueDeadlineAndPollDatagram(
        7,
        &server,
        discard_deadline,
        &client_dcid,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.key_discard, due.deadline.kind);
    try std.testing.expectEqual(@as(?[]u8, null), due.datagram);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));
}

