test "EndpointConnectionLifecycle pending work counts retained one RTT key discard" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{ .initial_rtt_ns = 100 });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{ .initial_rtt_ns = 100 });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.confirmHandshake();
    try server.confirmHandshake();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });

    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const update = (try client.pollProtectedShortDatagramWithInstalledKeys(100 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(update);
    try server.processProtectedShortDatagramWithInstalledKeys(100 * ms, server_dcid.len, update);
    const discard_deadline = server.oneRttKeyDiscardDeadline() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();
    const before_deadline = try lifecycle.processPendingWork(
        7,
        &server,
        discard_deadline - 1,
    );
    try std.testing.expect(before_deadline.idle_retired == null);
    try std.testing.expect(before_deadline.close_retired == null);
    try std.testing.expect(!before_deadline.key_discard_serviced);
    try std.testing.expect(before_deadline.recovery_serviced == null);
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    const connections = [_]EndpointConnectionReceiveView{.{
        .connection_id = 7,
        .connection = &server,
    }};
    const sweep = try lifecycle.processPendingWorkAcrossConnections(&connections, discard_deadline);
    try std.testing.expectEqual(@as(usize, 0), sweep.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), sweep.close_retired_count);
    try std.testing.expectEqual(@as(usize, 1), sweep.key_discard_serviced_count);
    try std.testing.expectEqual(@as(usize, 0), sweep.recovery_serviced_count);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));
}

test "EndpointConnectionLifecycle single pending-work selects after key discard" {
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var conn = try Connection.init(std.testing.allocator, .client, .{ .initial_rtt_ns = 100 });
    defer conn.deinit();
    const local_secret = @as([protection.traffic_secret_len]u8, @splat(0x8a));
    const peer_secret = @as([protection.traffic_secret_len]u8, @splat(0x8b));
    try conn.confirmHandshake();
    try conn.installOneRttTrafficSecrets(.{
        .local = local_secret,
        .peer = peer_secret,
    });
    conn.last_packet_activity_nanos = 10 * ms;
    try conn.initiateOneRttKeyUpdate();
    try std.testing.expectEqual(@as(?bool, true), conn.localOneRttRetainsKeyGeneration(0));

    const discard_deadline = conn.oneRttKeyDiscardDeadline() orelse return error.TestUnexpectedResult;
    const before = try lifecycle.processPendingWorkAndSelectNextDeadline(
        77,
        &conn,
        discard_deadline - 1,
    );
    try std.testing.expectEqual(@as(usize, 0), before.pending_work.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), before.pending_work.close_retired_count);
    try std.testing.expectEqual(@as(usize, 0), before.pending_work.key_discard_serviced_count);
    try std.testing.expectEqual(@as(usize, 0), before.pending_work.recovery_serviced_count);
    const unchanged = before.next_deadline orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 77), unchanged.connection_id);
    try std.testing.expectEqual(EndpointConnectionDeadlineKind.key_discard, unchanged.kind);
    try std.testing.expectEqual(discard_deadline, unchanged.deadline_nanos);
    try std.testing.expectEqual(@as(?bool, true), conn.localOneRttRetainsKeyGeneration(0));

    const serviced = try lifecycle.processPendingWorkAndSelectNextDeadline(
        77,
        &conn,
        discard_deadline,
    );
    try std.testing.expectEqual(@as(usize, 0), serviced.pending_work.idle_retired_count);
    try std.testing.expectEqual(@as(usize, 0), serviced.pending_work.close_retired_count);
    try std.testing.expectEqual(@as(usize, 1), serviced.pending_work.key_discard_serviced_count);
    try std.testing.expectEqual(@as(usize, 0), serviced.pending_work.recovery_serviced_count);
    try std.testing.expectEqual(@as(?bool, false), conn.localOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?EndpointConnectionDeadline, null), serviced.next_deadline);
}

test "EndpointConnectionLifecycle single pending-work poll reports key discard without polling output" {
    var lifecycle = EndpointConnectionLifecycle.init(std.testing.allocator);
    defer lifecycle.deinit();

    var conn = try Connection.init(std.testing.allocator, .client, .{ .initial_rtt_ns = 100 });
    defer conn.deinit();
