test "processProtectedShortDatagram accepts forward gaps and rejects tampered packets without mutation" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const plaintext = [_]u8{
        @backingInt(frame.FrameType.ping),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
    };

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();

    const wrong_packet_number = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 1,
    }, try packet.encodePacketNumberForHeader(1, null), secrets.client, &plaintext);
    defer std.testing.allocator.free(wrong_packet_number);

    try server.processProtectedShortDatagram(10 * ms, secrets.client, server_dcid.len, wrong_packet_number);
    try std.testing.expectEqual(@as(u64, 2), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 1), server.pendingAckLargest(.application));

    const tampered = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 0,
    }, try packet.encodePacketNumberForHeader(0, null), secrets.client, &plaintext);
    defer std.testing.allocator.free(tampered);
    tampered[tampered.len - 1] ^= 0x01;

    try std.testing.expectError(
        error.InvalidPacket,
        server.processProtectedShortDatagram(11 * ms, secrets.client, server_dcid.len, tampered),
    );
    try std.testing.expectEqual(@as(u64, 2), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 1), server.pendingAckLargest(.application));
}

test "processProtectedShortDatagram acknowledges reordered packets with ACK ranges and discards duplicates" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const plaintext = [_]u8{
        @backingInt(frame.FrameType.ping),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
    };

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.validatePeerAddress();

    const packet_zero = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 0,
    }, try packet.encodePacketNumberForHeader(0, null), secrets.client, &plaintext);
    defer std.testing.allocator.free(packet_zero);
    const packet_one = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 1,
    }, try packet.encodePacketNumberForHeader(1, null), secrets.client, &plaintext);
    defer std.testing.allocator.free(packet_one);
    const packet_two = try protection.protectShortPacketAes128(std.testing.allocator, .{
        .dcid = &server_dcid,
        .spin_bit = false,
        .key_phase = false,
        .packet_number = 2,
    }, try packet.encodePacketNumberForHeader(2, null), secrets.client, &plaintext);
    defer std.testing.allocator.free(packet_two);

    try server.processProtectedShortDatagram(10 * ms, secrets.client, server_dcid.len, packet_zero);
    try server.processProtectedShortDatagram(11 * ms, secrets.client, server_dcid.len, packet_two);
    try std.testing.expectEqual(@as(u64, 3), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 2), server.pendingAckLargest(.application));

    const ack_datagram = (try server.pollProtectedShortDatagram(12, &client_dcid, secrets.server)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ack_datagram);
    var opened_ack = try protection.unprotectShortPacketAes128(
        std.testing.allocator,
        secrets.server,
        ack_datagram,
        client_dcid.len,
        0,
    );
    defer protection.deinitProtectedShortPacket(&opened_ack, std.testing.allocator);
    var decoded_ack = try frame.decodeFrameSlice(opened_ack.packet.plaintext, std.testing.allocator);
    defer frame.deinitFrame(&decoded_ack.frame, std.testing.allocator);
    switch (decoded_ack.frame) {
        .ack => |ack| {
            try std.testing.expectEqual(@as(u64, 2), ack.largest_acknowledged);
            try std.testing.expectEqual(@as(u64, 0), ack.first_ack_range);
            try std.testing.expectEqual(@as(usize, 1), ack.ranges.len);
            try std.testing.expectEqual(@as(u64, 0), ack.ranges[0].gap);
            try std.testing.expectEqual(@as(u64, 0), ack.ranges[0].ack_range);
        },
        else => return error.TestUnexpectedResult,
    }

    try server.processProtectedShortDatagram(13 * ms, secrets.client, server_dcid.len, packet_one);
    try std.testing.expectEqual(@as(u64, 3), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 2), server.pendingAckLargest(.application));
    // A duplicate packet is discarded (RFC 9000 §13.1), not a connection error.
    try server.processProtectedShortDatagram(14 * ms, secrets.client, server_dcid.len, packet_one);
    try std.testing.expectEqual(@as(u64, 3), server.nextPeerPacketNumber(.application));
    try std.testing.expectEqual(@as(?u64, 2), server.pendingAckLargest(.application));
}

test "pacing query retains only an actual blocked poll without consuming state" {
    const dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
    const secrets = try protection.deriveInitialSecrets(.v1, &dcid);
    var conn = try Connection.init(std.testing.allocator, .client, .{ .max_datagram_size = 1200 });
    defer conn.deinit();
    try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
    try std.testing.expectError(error.InvalidPacket, conn.pollProtectedShortDatagramWithInstalledKeys(0, &dcid));
    try conn.confirmHandshake();
    const stream_id = try conn.openStream();
    try conn.sendOnStream(stream_id, "paced payload", false);
    conn.recovery_state.min_rtt_ns = 100 * ms;
    conn.recovery_state.smoothed_rtt_ns = 100 * ms;
    conn.recovery_state.congestion_window = 12_000;
    conn.tx_pacer.budget = 0;
    conn.tx_pacer.last_sent_ns = 0;
    try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
    try std.testing.expect(try conn.pollProtectedShortDatagram(0, &dcid, secrets.client) == null);
    const before = conn.tx_pacer;
    try std.testing.expectEqual(@as(?i64, 8 * ms), conn.pacingDeadline());
    try std.testing.expectEqual(@as(?i64, 8 * ms), conn.pacingDeadline());
    try std.testing.expectEqualDeep(before, conn.tx_pacer);
    try std.testing.expectEqual(@as(u64, 0), conn.nextPacketNumber(.application));
    try std.testing.expectEqualStrings("paced payload", conn.send_queue.items[0].data);

    try std.testing.expectError(error.InvalidPacket, conn.pollProtectedShortDatagramWithInstalledKeys(0, &dcid));
    try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
    try std.testing.expect(try conn.pollProtectedShortDatagram(0, &dcid, secrets.client) == null);
    try conn.closeApplication(0, "closed");
    try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
}

test "pacing output keeps congestion admission and queued control state" {
    for ([_]bool{ false, true }) |has_path_response| {
        const dcid = [_]u8{ 0x10, 0x20, 0x30, 0x40 };
        const secrets = try protection.deriveInitialSecrets(.v1, &dcid);
        var conn = try Connection.init(std.testing.allocator, .client, .{ .max_datagram_size = 1200 });
        defer conn.deinit();
        try conn.confirmHandshake();
        if (has_path_response) {
            var input: [32]u8 = undefined;
            var out = buffer.fixedWriter(&input);
            try frame.encodeFrame(out.writer(), .{ .path_challenge = .{ .data = .{ 1, 2, 3, 4, 5, 6, 7, 8 } } });
            try conn.processDatagram(0, out.getWritten());
        }
        const stream_id = try conn.openStream();
        try conn.sendOnStream(stream_id, "paced payload", false);
        conn.recovery_state.min_rtt_ns = 100 * ms;
        conn.recovery_state.smoothed_rtt_ns = 100 * ms;
        conn.recovery_state.congestion_window = 12_000;
        conn.recovery_state.bytes_in_flight = 12_000;
        conn.tx_pacer.budget = 0;
        conn.tx_pacer.last_sent_ns = 0;
        try std.testing.expect(try conn.pollProtectedShortDatagram(0, &dcid, secrets.client) == null);
        try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
        conn.tx_pacer.budget = conn.tx_pacer.maxBurstSize();
        try std.testing.expect(try conn.pollProtectedShortDatagram(0, &dcid, secrets.client) == null);
        try std.testing.expectEqual(@as(?i64, null), conn.pacingDeadline());
        try std.testing.expectEqual(@as(u64, 0), conn.nextPacketNumber(.application));
        try std.testing.expectEqual(@as(usize, 1), conn.send_queue.items.len);
        try std.testing.expectEqual(@as(usize, @intFromBool(has_path_response)), conn.pending_path_responses.items.len);
    }
}

