    try frame.encodeFrame(update_out.writer(), .{ .max_stream_data = .{
        .stream_id = stream_id,
        .maximum_stream_data = 2,
    } });
    try conn.processDatagram(0 * ms, update_out.getWritten());

    try std.testing.expect(conn.findRecvStream(1) != null);
