    try std.testing.expectEqualStrings("hello!", read_buf[0..n]);
    try std.testing.expect(try conn.recvStreamFinished(0));
    try std.testing.expectEqual(@as(?usize, null), try conn.recvOnStream(0, &read_buf));
}

