    defer std.testing.allocator.free(client_dgram);

    // 2. Server consumes ClientHello, installs handshake keys.
    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, client_dgram);
    const server_progress = try server.driveCryptoBackendInSpace(
        .initial,
        server_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(server_progress.inbound_bytes > 0);
    try std.testing.expect(server_progress.handshake_keys_installed);
}

test "Tls13Backend client Connection withholds unauthenticated server parameters on certificate failure" {
    const X25519 = std.crypto.dh.X25519;
    const alpn_proto = "hq-interop";
    const alpn = [_][]const u8{alpn_proto};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .max_datagram_size = 8192,
    });
    defer client.deinit();

    var client_backend = tls13_backend.Tls13Backend.initClient(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = false,
    });

    var scratch: [8192]u8 = undefined;
    const client_hello_progress = try client.driveCryptoBackendInSpace(
        .initial,
        client_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(client_hello_progress.outbound_bytes > 0);
    try std.testing.expect(!client_hello_progress.peer_transport_parameters_applied);
    try std.testing.expect(!client_hello_progress.handshake_confirmed);

    var server_secret: [32]u8 = undefined;
    tls13.secureRandomBytes(&server_secret);
    const server_public = X25519.recoverPublicKey(server_secret);
    var server_hello_buf: [128]u8 = undefined;
    const server_hello_len = tls13.buildServerHello(&server_hello_buf, server_public, 0x1301, true, true);

    var initial_datagram: [256]u8 = undefined;
    var initial_out = buffer.fixedWriter(&initial_datagram);
    try frame.encodeFrame(initial_out.writer(), .{ .crypto = .{
        .offset = 0,
        .data = server_hello_buf[0..server_hello_len],
    } });
    try client.processDatagramInSpace(.initial, 10, initial_out.getWritten());

    const initial_progress = try client.driveCryptoBackendInSpace(
        .initial,
        client_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(initial_progress.handshake_keys_installed);
    try std.testing.expect(!initial_progress.peer_transport_parameters_applied);
    try std.testing.expect(!initial_progress.handshake_confirmed);

    var peer_tp_buf: [160]u8 = undefined;
    var peer_tp_out = buffer.fixedWriter(&peer_tp_buf);
    try transport_parameters.encode(peer_tp_out.writer(), .{
        .initial_max_data = 4321,
        .max_udp_payload_size = 1400,
    });
    const peer_tp = peer_tp_out.getWritten();

    var ee_buf: [256]u8 = undefined;
    const ee_len = tls13.buildEncryptedExtensions(&ee_buf, alpn_proto, peer_tp);
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };
    var cert_buf: [512]u8 = undefined;
    const cert_len = tls13.buildCertificate(&cert_buf, &cert_der);

    var flight: [1024]u8 = undefined;
    var flight_len: usize = 0;
    @memcpy(flight[flight_len..][0..ee_len], ee_buf[0..ee_len]);
    flight_len += ee_len;
    @memcpy(flight[flight_len..][0..cert_len], cert_buf[0..cert_len]);
    flight_len += cert_len;

    var handshake_datagram: [1200]u8 = undefined;
    var handshake_out = buffer.fixedWriter(&handshake_datagram);
    try frame.encodeFrame(handshake_out.writer(), .{ .crypto = .{
        .offset = 0,
        .data = flight[0..flight_len],
    } });
    try client.processDatagramInSpace(.handshake, 20, handshake_out.getWritten());

    try std.testing.expectError(error.CryptoError, client.driveCryptoBackendInSpace(
        .handshake,
        client_backend.cryptoBackend(),
        &scratch,
    ));
    try std.testing.expect(client_backend.hs.peer_tp_available);
    try std.testing.expect(client_backend.hs.negotiated_alpn_len != 0);
    try std.testing.expectEqual(@as(u64, 65_536), client.peer_max_data);
    try std.testing.expect(!client.hasOneRttProtectionKeys());
    try std.testing.expect(!client.handshakeConfirmed());
}

test "Tls13Backend + Connection: PTO probe fires after ACK loss on TLS-owned path" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };
    const alpn = [_][]const u8{"hq-interop"};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClient(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    });
    var server_backend = tls13_backend.Tls13Backend.initServer(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    });

    var scratch: [8192]u8 = undefined;

    // Complete the handshake (in-memory datagram exchange).
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    const ch_dgram = (try client.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        0,
        &original_dcid,
        &client_scid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch_dgram);

    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch_dgram);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    try std.testing.expect(server.hasHandshakeProtectionKeys());

    const sh_dgram = (try server.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        2,
        &client_scid,
        &server_scid,
        &[_]u8{},
        secrets.server,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(sh_dgram);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);
    const shs_dgram = (try server.pollProtectedHandshakeDatagramWithInstalledKeys(
        3,
        &client_scid,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(shs_dgram);

    try client.processProtectedLongDatagramInSpace(.initial, 4, secrets.server, sh_dgram);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(5 * ms, shs_dgram);
    const client_hs = try client.driveCryptoBackendInSpace(
        .handshake,
        client_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(client_hs.one_rtt_keys_installed);

    const cf_dgram = (try client.pollProtectedHandshakeDatagramWithInstalledKeys(
        6,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(cf_dgram);

    try server.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, cf_dgram);
    const server_final = try server.driveCryptoBackendInSpace(
        .handshake,
        server_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(server_final.handshake_confirmed);

    // Now client sends a PING over 1-RTT (in-flight), but server never ACKs (loss).
    try client.sendPing();
    const ping_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(
        8,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ping_dgram);
    try std.testing.expect(client.bytesInFlight(.application) > 0);

    // Advance time well past PTO deadline and service loss detection.
    _ = try client.serviceLossDetectionTimer(1000000 * ms);

    // The client must still have bytes in flight (no ACK received).
    try std.testing.expect(client.bytesInFlight(.application) > 0);
}

test "Tls13Backend + Connection: PTO probe fires and backoffs on TLS-owned path after handshake confirmation" {
    // 区别于 "PTO probe fires after ACK loss"：本测试先让 client 接收 HANDSHAKE_DONE
    // 进入 handshake_confirmed，使 application PTO 真正 allowed，再验证 PTO probe 通过
    // pollProtectedShortDatagramWithInstalledKeys 发出 + pto_count 递增 + backoff。
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };
    const alpn = [_][]const u8{"hq-interop"};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClient(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    });
    var server_backend = tls13_backend.Tls13Backend.initServer(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    });

    var scratch: [8192]u8 = undefined;

    // Complete the handshake (in-memory datagram exchange).
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    const ch_dgram = (try client.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        0,
        &original_dcid,
        &client_scid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch_dgram);

    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch_dgram);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    try std.testing.expect(server.hasHandshakeProtectionKeys());

    const sh_dgram = (try server.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        2,
        &client_scid,
        &server_scid,
        &[_]u8{},
        secrets.server,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(sh_dgram);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);
    const shs_dgram = (try server.pollProtectedHandshakeDatagramWithInstalledKeys(
        3,
        &client_scid,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(shs_dgram);

    try client.processProtectedLongDatagramInSpace(.initial, 4, secrets.server, sh_dgram);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(5 * ms, shs_dgram);
    const client_hs = try client.driveCryptoBackendInSpace(
        .handshake,
        client_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(client_hs.one_rtt_keys_installed);

    const cf_dgram = (try client.pollProtectedHandshakeDatagramWithInstalledKeys(
        6,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(cf_dgram);

    try server.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, cf_dgram);
    _ = try server.driveCryptoBackendInSpace(
        .handshake,
        server_backend.cryptoBackend(),
        &scratch,
    );

    // Server emits HANDSHAKE_DONE over 1-RTT; client receives it -> handshake_confirmed.
    // 只有 handshake_confirmed 后 application PTO 才被 allowed（RFC 9002 §6.2.2）。
    try server.sendHandshakeDone();
    const hd_dgram = (try server.pollProtectedShortDatagramWithInstalledKeys(8 * ms, &client_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(hd_dgram);
    try client.processProtectedShortDatagramWithInstalledKeys(9 * ms, client_scid.len, hd_dgram);
    try std.testing.expect(client.handshake_confirmed);

    // Client sends PING over 1-RTT (in-flight, ack-eliciting)，server 不 ACK（模拟丢失）。
    try client.sendPing();
    const ping_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(
        10,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ping_dgram);
    try std.testing.expect(client.bytesInFlight(.application) > 0);
    try std.testing.expectEqual(@as(u8, 0), client.recovery_state.pto_count);

    // 推进时钟远超 PTO deadline -> PTO 触发：pto_count 0->1，probe 排队。
    _ = try client.serviceLossDetectionTimer(1_000_000 * ms);
    try std.testing.expectEqual(@as(u8, 1), client.recovery_state.pto_count);
    try std.testing.expectEqual(@as(usize, 1), client.pending_ping_count);

    // poll PTO probe（加密 PING datagram）over 1-RTT。
    const probe_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(
        1_000_001,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(probe_dgram);
    try std.testing.expect(probe_dgram.len > 0);
    try std.testing.expectEqual(@as(usize, 0), client.pending_ping_count);

    // 推进时钟远超 backoff deadline（基于 probe sent_time + 2*basePto）-> pto_count 1->2。
    _ = try client.serviceLossDetectionTimer(10_000_000 * ms);
    try std.testing.expectEqual(@as(u8, 2), client.recovery_state.pto_count);
    try std.testing.expectEqual(@as(usize, 1), client.pending_ping_count);
}

test "Tls13Backend + Connection: RESET_STREAM closes send side on TLS-owned path" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };
    const alpn = [_][]const u8{"hq-interop"};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClient(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    });
    var server_backend = tls13_backend.Tls13Backend.initServer(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    });

    var scratch: [8192]u8 = undefined;

    // Complete the handshake (in-memory).
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    const ch = (try client.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        0,
        &original_dcid,
        &client_scid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch);
    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    const sh = (try server.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        2,
        &client_scid,
        &server_scid,
        &[_]u8{},
        secrets.server,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(sh);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);
    const shs = (try server.pollProtectedHandshakeDatagramWithInstalledKeys(
        3,
        &client_scid,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(shs);
    try client.processProtectedLongDatagramInSpace(.initial, 4, secrets.server, sh);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(5 * ms, shs);
    _ = try client.driveCryptoBackendInSpace(.handshake, client_backend.cryptoBackend(), &scratch);
    const cf = (try client.pollProtectedHandshakeDatagramWithInstalledKeys(
        6,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(cf);
    try server.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, cf);
    const sf = try server.driveCryptoBackendInSpace(
        .handshake,
        server_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(sf.handshake_confirmed);

    // Client opens a stream, sends data, then resets it.
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "hello", false);
    try client.resetStream(stream_id, 42);

    // The reset must produce a 1-RTT datagram containing RESET_STREAM.
    const reset_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(
        8,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(reset_dgram);
    try std.testing.expect(reset_dgram.len > 0);

    // Server receives and processes the RESET_STREAM.
    try server.processProtectedShortDatagramWithInstalledKeys(9 * ms, server_scid.len, reset_dgram);

    // After reset, the stream's send side is closed on the client.
    // Attempting to send more data on a reset stream should fail.
    try std.testing.expectError(error.StreamClosed, client.sendOnStream(stream_id, "more", false));
}

