    // Client detects the reset and enters draining.
    const seq = client.processStatelessResetDatagram(12, reset_dgram) orelse return error.UnexpectedState;
    try std.testing.expectEqual(@as(u64, 0), seq);
    // After the reset, further sends fail because the connection is closing.
    try std.testing.expectError(error.ConnectionClosed, client.sendOnStream(0, "x", false));
}

