    try client.processProtectedLongDatagramInSpace(.initial, 4, secrets.server, sh);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(5 * ms, shs);
    _ = try client.driveCryptoBackendInSpace(.handshake, client_backend.cryptoBackend(), &scratch);
    const cf = (try client.pollProtectedHandshakeDatagramWithInstalledKeys(6 * ms, &server_scid, &client_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(cf);
    try server.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, cf);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);

    try tls13_test_support.confirmClient(&client, &server, &client_scid, 7 * ms + 1);

    // Client sends a PING over 1-RTT (in-flight, never ACKed).
    try client.sendPing();
    const ping_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(8 * ms, &server_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ping_dgram);
    const deadline1 = client.ptoDeadline(.application) orelse return error.UnexpectedState;

    // Service the PTO: a probe is sent and the PTO backoff count increments.
    _ = (try client.serviceLossDetectionTimer(1_000_000 * ms)) orelse return error.UnexpectedState;
    const pto_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(1_000_001, &server_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(pto_dgram);
    const deadline2 = client.ptoDeadline(.application) orelse return error.UnexpectedState;

    // The backed-off PTO deadline must be later than the original.
    try std.testing.expect(deadline2 > deadline1);
}

test "Tls13Backend + Connection: initiateOneRttKeyUpdate on TLS-owned path" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };
    const alpn = [_][]const u8{"hq-interop"};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClient(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    });
    var server_backend = tls13_backend.Tls13Backend.initServer(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    });
    var scratch: [8192]u8 = undefined;

    // Complete the handshake.
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    const ch = (try client.pollProtectedLongCryptoDatagramInSpace(.initial, 0, &original_dcid, &client_scid, &[_]u8{}, secrets.client)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch);
    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    const sh = (try server.pollProtectedLongCryptoDatagramInSpace(.initial, 2, &client_scid, &server_scid, &[_]u8{}, secrets.server)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(sh);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);
    const shs = (try server.pollProtectedHandshakeDatagramWithInstalledKeys(3 * ms, &client_scid, &server_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(shs);
    try client.processProtectedLongDatagramInSpace(.initial, 4, secrets.server, sh);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(5 * ms, shs);
    _ = try client.driveCryptoBackendInSpace(.handshake, client_backend.cryptoBackend(), &scratch);
    const cf = (try client.pollProtectedHandshakeDatagramWithInstalledKeys(6 * ms, &server_scid, &client_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(cf);
    try server.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, cf);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);

    try tls13_test_support.confirmClient(&client, &server, &client_scid, 7 * ms + 1);

    // Client initiates a 1-RTT key update via the Connection API: this
    // advances the internal key-phase state (and arms the ack threshold),
    // unlike the caller-owned key-phase-state variant.
    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const ku_dgram = (try client.pollProtectedShortDatagramWithInstalledKeys(8 * ms, &server_scid)) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ku_dgram);

    // Server processes the key-update packet with its peer (receive) state.
    var server_state = server.peer_one_rtt_key_phase_state.?;
    try server.processProtectedShortDatagramWithKeyPhaseState(9, &server_state, server_scid.len, ku_dgram);
    try std.testing.expectEqual(@as(u64, 1), server_state.keyUpdateCount());
}

test "Tls13Backend + Connection: PSK installs 0-RTT keys via traffic-secret hook on TLS-owned path" {
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const alpn = [_][]const u8{"hq-interop"};

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    try client.setLocalInitialSourceConnectionId(&client_scid);

    // A resumption PSK (normally derived from a prior session's
    // NewSessionTicket). Seeding the backend with it arms the 0-RTT path:
    // the ClientHello is built with early-data intent and the key schedule
    // carries a PSK-based early secret.
    const resumption_psk = @as([tls13.secret_len]u8, @splat(0xab));
    var client_backend = tls13_backend.Tls13Backend.initClientWithPsk(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    }, resumption_psk);
    const session_ticket = [_]u8{ 0xcc, 0xdd, 0xee, 0xff };
    @memcpy(client_backend.hs.session_ticket[0..session_ticket.len], &session_ticket);
    client_backend.hs.session_ticket_len = session_ticket.len;
    client_backend.hs.session_ticket_allows_early_data = true;

    var scratch: [8192]u8 = undefined;

    // Driving the Initial space builds the ClientHello. The CryptoBackend
    // pump emits the ClientHello (arming client_hello_built); the connection
    // then pulls traffic secrets. pullZeroRttTrafficSecrets derives the
    // early traffic secret from the PSK-based early secret and the
    // ClientHello transcript, and the connection installs it as the local
    // 0-RTT packet-protection key.
    const progress = try client.driveCryptoBackendInSpace(
        .initial,
        client_backend.cryptoBackend(),
        &scratch,
    );
    try std.testing.expect(progress.zero_rtt_keys_installed);
    try std.testing.expect(client.hasLocalZeroRttProtectionKey());
    // Client only installs the local (send) side; peer 0-RTT keys come from
    // the server accepting early data, which has not happened yet.
    try std.testing.expect(!client.hasPeerZeroRttProtectionKey());

    // With 0-RTT keys installed, the client can emit early data before the
    // handshake completes: open a stream and protect a 0-RTT datagram.
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "early data", true);
    const zero_rtt = (try client.pollProtectedZeroRttDatagramWithInstalledKeys(
        0,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(zero_rtt);
    try std.testing.expect(zero_rtt.len > 0);
}

test "Tls13Backend + Connection: 0-RTT early data round-trip on TLS-owned path" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const alpn = [_][]const u8{"hq-interop"};
    const psk = @as([tls13.secret_len]u8, @splat(0xab));
    const ticket = [_]u8{ 0xcc, 0xdd, 0xee, 0xff };
    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClientWithPsk(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    }, psk);
    @memcpy(client_backend.hs.session_ticket[0..ticket.len], &ticket);
    client_backend.hs.session_ticket_len = ticket.len;
    client_backend.hs.session_ticket_allows_early_data = true;

    var server_backend = tls13_backend.Tls13Backend.initServerWithPsk(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    }, psk);

    var scratch: [8192]u8 = undefined;

    // Client drives Initial: builds ClientHello + installs 0-RTT local keys.
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try std.testing.expect(client.hasLocalZeroRttProtectionKey());

    // Emit the ClientHello datagram (Initial-protected).
    const ch = (try client.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        0,
        &original_dcid,
        &client_scid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch);

    // Server processes ClientHello: parses the PSK offer, derives the client
    // early traffic secret, and installs it as the peer (receive) 0-RTT key.
    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    try std.testing.expect(server.hasPeerZeroRttProtectionKey());
    try server.acceptZeroRtt();
    try std.testing.expect(server.zeroRttAccepted());

    // Client emits 0-RTT early data on a stream before the handshake finishes.
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "early data", true);
    const zero_rtt = (try client.pollProtectedZeroRttDatagramWithInstalledKeys(
        2,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(zero_rtt);

    // Server opens the 0-RTT datagram with installed + accepted peer keys.
    try server.processProtectedZeroRttDatagramWithInstalledKeys(3 * ms, zero_rtt);
    var recv_buf: [32]u8 = undefined;
    const recv_len = (try server.recvOnStream(stream_id, &recv_buf)) orelse return error.UnexpectedState;
    try std.testing.expectEqualStrings("early data", recv_buf[0..recv_len]);
}

test "Tls13Backend + Connection: NewSessionTicket lets client derive resumption PSK" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;

    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
