test "Tls13Backend + Connection: accept_zero_rtt=false ignores early data" {
    const EcdsaP256Sha256 = std.crypto.sign.ecdsa.EcdsaP256Sha256;
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const client_scid = [_]u8{ 0x21, 0x22, 0x23, 0x24 };
    const server_scid = [_]u8{ 0x31, 0x32, 0x33, 0x34 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);
    const alpn = [_][]const u8{"hq-interop"};
    const psk = @as([tls13.secret_len]u8, @splat(0xab));
    const ticket = [_]u8{ 0xcc, 0xdd, 0xee, 0xff };
    const seed = @as([32]u8, @splat(0x55));
    const server_kp = try EcdsaP256Sha256.KeyPair.generateDeterministic(seed);
    const server_priv = server_kp.secret_key.bytes;
    const cert_der = [_]u8{ 0x30, 0x82, 0x01, 0x00, 0xDE, 0xAD, 0xBE, 0xEF };

    var client = try Connection.init(std.testing.allocator, .client, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer client.deinit();
    // Server keeps the safe default accept_zero_rtt=false: drive installs peer
    // 0-RTT keys but does not accept them, so early data is ignored without a
    // manual acceptZeroRtt()/rejectZeroRtt() call.
    var server = try Connection.init(std.testing.allocator, .server, .{
        .initial_max_data = 8192,
        .initial_max_stream_data = 2048,
        .initial_max_streams_bidi = 8,
        .max_datagram_size = 8192,
    });
    defer server.deinit();
    try server.validatePeerAddress();
    try client.setLocalInitialSourceConnectionId(&client_scid);
    try server.setLocalInitialSourceConnectionId(&server_scid);

    var client_backend = tls13_backend.Tls13Backend.initClientWithPsk(.{
        .alpn = &alpn,
        .server_name = "example.com",
        .skip_cert_verify = true,
    }, psk);
    @memcpy(client_backend.hs.session_ticket[0..ticket.len], &ticket);
    client_backend.hs.session_ticket_len = ticket.len;
    client_backend.hs.session_ticket_allows_early_data = true;

    var server_backend = tls13_backend.Tls13Backend.initServerWithPsk(.{
        .alpn = &alpn,
        .cert_chain_der = &.{&cert_der},
        .private_key_bytes = &server_priv,
        .private_key_algorithm = .ecdsa_p256_sha256,
    }, psk);

    var scratch: [8192]u8 = undefined;

    // Client drives Initial: builds ClientHello + installs 0-RTT local keys.
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try std.testing.expect(client.hasLocalZeroRttProtectionKey());

    const ch = (try client.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        0,
        &original_dcid,
        &client_scid,
        &[_]u8{},
        secrets.client,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(ch);

    // Server parses the PSK offer, verifies the binder, derives the early
    // secret, and installs peer 0-RTT keys. The configured policy left the
    // keys installed but not accepted.
    try server.processProtectedLongDatagramInSpace(.initial, 1, secrets.client, ch);
    _ = try server.driveCryptoBackendInSpace(.initial, server_backend.cryptoBackend(), &scratch);
    try std.testing.expect(server_backend.hs.peer_psk_binder_valid);
    try std.testing.expect(!server_backend.hs.server_accepts_early_data);
    try std.testing.expect(server.hasPeerZeroRttProtectionKey());
    try std.testing.expect(!server.zeroRttAccepted());

    // Client still emits 0-RTT early data (it does not yet know the server
    // will ignore it).
    const stream_id = try client.openStream();
    try client.sendOnStream(stream_id, "early data", true);
    const zero_rtt = (try client.pollProtectedZeroRttDatagramWithInstalledKeys(
        2,
        &server_scid,
        &client_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(zero_rtt);

    // Server cannot open the 0-RTT datagram: keys are installed but not
    // accepted per the configured policy.
    try std.testing.expectError(
        error.InvalidPacket,
        server.processProtectedZeroRttDatagramWithInstalledKeys(3 * ms, zero_rtt),
    );

    // No early data was delivered to the stream.
    var recv_buf: [32]u8 = undefined;
    try std.testing.expect((try server.recvOnStream(stream_id, &recv_buf)) == null);

    // The TLS server flight omits EncryptedExtensions early_data. Once the
    // client processes that rejection, it discards its local 0-RTT send keys
    // before 1-RTT secrets are installed.
    const sh = (try server.pollProtectedLongCryptoDatagramInSpace(
        .initial,
        4,
        &client_scid,
        &server_scid,
        &[_]u8{},
        secrets.server,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(sh);
    _ = try server.driveCryptoBackendInSpace(.handshake, server_backend.cryptoBackend(), &scratch);
    const shs = (try server.pollProtectedHandshakeDatagramWithInstalledKeys(
        5,
        &client_scid,
        &server_scid,
    )) orelse return error.UnexpectedState;
    defer std.testing.allocator.free(shs);
    try client.processProtectedLongDatagramInSpace(.initial, 6, secrets.server, sh);
    _ = try client.driveCryptoBackendInSpace(.initial, client_backend.cryptoBackend(), &scratch);
    try client.processProtectedHandshakeDatagramWithInstalledKeys(7 * ms, shs);
    const rejection = try client.driveCryptoBackendInSpace(.handshake, client_backend.cryptoBackend(), &scratch);
    try std.testing.expectEqual(false, rejection.zero_rtt_accepted.?);
    try std.testing.expect(rejection.zero_rtt_keys_discarded);
    try std.testing.expect(!client.hasLocalZeroRttProtectionKey());
}

test "checkPtoTimeouts discards retained peer previous key after one PTO" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });
    try client.confirmHandshake();
    try server.confirmHandshake();

    // Client initiates a key update and sends a PING with the new key phase.
    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const ping = (try client.pollProtectedShortDatagramWithInstalledKeys(
        10,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ping);

    // Server receives the gen-1 PING: peer state advances and the old gen-0
    // receive key is retained for one PTO (RFC 9001 §6.5 / RFC 9002 §6.2).
    try server.processProtectedShortDatagramWithInstalledKeys(11 * ms, server_dcid.len, ping);
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    // Within the PTO retain window the previous key is still held.
    try server.checkPtoTimeouts(12 * ms);
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    // After the PTO retain window expires the previous key is discarded.
    try server.checkPtoTimeouts(10_000 * ms);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(1));
}

test "delayed previous-key packet opens without advancing peer key phase" {
    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });
    try client.confirmHandshake();
    try server.confirmHandshake();

    // Client initiates a key update and sends a PING with the gen-1 key phase.
    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const ping = (try client.pollProtectedShortDatagramWithInstalledKeys(
        10,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ping);

    // Server receives the gen-1 PING: peer state advances to gen 1 and the old
    // gen-0 receive key is retained for one PTO (RFC 9001 §6.5).
    try server.processProtectedShortDatagramWithInstalledKeys(11 * ms, server_dcid.len, ping);
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));

    // A packet protected with the retained gen-0 key (key phase false) must
    // still be opened via the previous-generation branch. Its revealed phase
    // bit equals the toggled value of `next`, so only the next-before-previous
    // ordering in unprotect plus the peer_initiated_key_update signal keep the
    // receive path from advancing on this delayed old-key packet.
    const delayed_plaintext = [_]u8{
        @backingInt(frame.FrameType.ping),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
    };
    const delayed_ping = try protection.protectShortPacketAes128(
        std.testing.allocator,
        .{
            .dcid = &server_dcid,
            .key_phase = false,
            .packet_number = 1,
        },
        try packet.encodePacketNumberForHeader(1, null),
        secrets.client,
        &delayed_plaintext,
    );
    defer std.testing.allocator.free(delayed_ping);
    try server.processProtectedShortDatagramWithInstalledKeys(12 * ms, server_dcid.len, delayed_ping);
    // The delayed old-key packet must NOT advance peer key-phase state.
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(0));
    try std.testing.expectEqual(@as(?bool, true), server.peerOneRttRetainsKeyGeneration(1));

    // After the PTO retain window expires the previous key is discarded; a
    // further old-key packet then fails to authenticate (RFC 9001 §6.5).
    try server.checkPtoTimeouts(10_000 * ms);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));
    const stale_ping = try protection.protectShortPacketAes128(
        std.testing.allocator,
        .{
            .dcid = &server_dcid,
            .key_phase = false,
            .packet_number = 2,
        },
        try packet.encodePacketNumberForHeader(2, null),
        secrets.client,
        &delayed_plaintext,
    );
    defer std.testing.allocator.free(stale_ping);
    try std.testing.expectError(
        error.InvalidPacket,
        server.processProtectedShortDatagramWithInstalledKeys(13 * ms, server_dcid.len, stale_ping),
    );
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());
}

