    const original_dcid = [_]u8{ 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08 };
    const server_dcid = [_]u8{ 0xaa, 0xbb, 0xcc, 0xdd };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try client.installOneRttTrafficSecrets(.{
        .local = secrets.client.secret,
        .peer = secrets.server.secret,
    });
    try server.installOneRttTrafficSecrets(.{
        .local = secrets.server.secret,
        .peer = secrets.client.secret,
    });
    try client.confirmHandshake();
    try server.confirmHandshake();

    // Client initiates a key update; server advances and retains gen-0.
    try client.initiateOneRttKeyUpdate();
    try client.sendPing();
    const ping = (try client.pollProtectedShortDatagramWithInstalledKeys(
        10,
        &server_dcid,
    )) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(ping);
    try server.processProtectedShortDatagramWithInstalledKeys(11 * ms, server_dcid.len, ping);
    try std.testing.expectEqual(@as(?u64, 1), server.peerOneRttKeyUpdateCount());

    // Discard the retained previous key past the PTO retain window.
    try server.checkPtoTimeouts(10_000 * ms);
    try std.testing.expectEqual(@as(?bool, false), server.peerOneRttRetainsKeyGeneration(0));

    // Once its key is gone, this packet cannot authenticate a peer violation.
    const stale_plaintext = [_]u8{
        @backingInt(frame.FrameType.ping),
        @backingInt(frame.FrameType.padding),
        @backingInt(frame.FrameType.padding),
    };
    const stale_ping = try protection.protectShortPacketAes128(
        std.testing.allocator,
        .{
            .dcid = &server_dcid,
            .key_phase = false,
            .packet_number = 1,
        },
        try packet.encodePacketNumberForHeader(1, null),
        secrets.client,
        &stale_plaintext,
    );
    defer std.testing.allocator.free(stale_ping);
    try std.testing.expectError(
        error.InvalidPacket,
        server.processProtectedShortDatagramWithInstalledKeys(10_001 * ms, server_dcid.len, stale_ping),
    );
    try std.testing.expectEqual(ConnectionState.active, server.connectionState());
    try std.testing.expectEqual(@as(?u64, null), server.pendingCloseErrorCode());
    try client.sendPing();
    const current_ping = (try client.pollProtectedShortDatagramWithInstalledKeys(10_002 * ms, &server_dcid)) orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.free(current_ping);
    try server.processProtectedShortDatagramWithInstalledKeys(10_003 * ms, server_dcid.len, current_ping);
    try std.testing.expectEqual(@as(u64, 2), server.nextPeerPacketNumber(.application));
}

test "sendDatagram and recvDatagram roundtrip through pollTx and frame processing" {
    var sender = try Connection.init(std.testing.allocator, .client, .{
        .max_datagram_frame_size = 1200,
    });
    defer sender.deinit();
    try sender.confirmHandshake();

    var receiver = try Connection.init(std.testing.allocator, .server, .{
        .max_datagram_frame_size = 1200,
    });
    defer receiver.deinit();
    try receiver.confirmHandshake();
    try receiver.validatePeerAddress();

    // Sender queues a datagram.
    try sender.sendDatagram("hello datagram");
    try std.testing.expectEqual(@as(usize, 1), sender.pendingDatagramCount());

    // Sender polls the datagram frame.
    var out_buf: [1500]u8 = undefined;
    const payload = (try sender.pollTx(0 * ms, &out_buf)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 0), sender.pendingDatagramCount());

    // Receiver processes the datagram frame.
    try receiver.processDatagramForPacketType(
        .one_rtt,
        0,
        payload,
    );
    try std.testing.expectEqual(@as(usize, 1), receiver.receivedDatagramCount());

    // Receiver reads the datagram.
    var recv_buf: [256]u8 = undefined;
    const n = (try receiver.recvDatagram(&recv_buf)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("hello datagram", recv_buf[0..n]);
    try std.testing.expectEqual(@as(usize, 0), receiver.receivedDatagramCount());
}

test "connection multipath enable and path management" {
    var conn = try Connection.init(std.testing.allocator, .client, .{});
    defer conn.deinit();

    // Multipath disabled by default
    try std.testing.expect(!conn.isMultipathEnabled());
    try std.testing.expectEqual(@as(usize, 1), conn.activePathCount());

    // Enable multipath
    try conn.enableMultipath(std.testing.allocator);
    try std.testing.expect(conn.isMultipathEnabled());
    try std.testing.expectEqual(@as(usize, 1), conn.activePathCount());

    // Add a second path
    if (conn.multipath) |*mp| {
        _ = try mp.addPath();
        try std.testing.expectEqual(@as(usize, 2), conn.activePathCount());

        // Abandon first path
        try conn.abandonPath(0);
        try std.testing.expectEqual(@as(usize, 1), conn.activePathCount());
    }

    // Cleanup multipath
    if (conn.multipath) |*mp| {
        mp.deinit();
    }
}

test "connectionStats reports stream bytes sent and recovery counters" {
    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try client.installOneRttTrafficSecrets(.{ .local = @as([32]u8, @splat(0x11)), .peer = @as([32]u8, @splat(0x22)) });
    try client.confirmHandshake();
    const sid = try client.openStream();
    try client.sendOnStream(sid, "hello", false);
    const stats = client.connectionStats();
    try std.testing.expectEqual(@as(u64, 5), stats.stream_bytes_sent);
    try std.testing.expect(stats.congestion_window > 0);
    try std.testing.expectEqual(@as(u64, 0), stats.packets_lost);
}

test "0-RTT end-to-end early data STREAM reaches server before handshake" {
    const original_dcid = [_]u8{ 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 };
    const secrets = try protection.deriveInitialSecrets(.v1, &original_dcid);

    var client = try Connection.init(std.testing.allocator, .client, .{});
    defer client.deinit();
    try client.installZeroRttTrafficSecrets(.{ .local = secrets.client.secret });
    try client.confirmHandshake();

    const sid = try client.openStream();
    try client.sendOnStream(sid, "early-data", false);
    const dg = try client.pollProtectedZeroRttDatagramWithInstalledKeys(0, &[_]u8{ 0xaa, 0xbb, 0xcc, 0xdd }, &[_]u8{ 0x11, 0x22, 0x33, 0x44 }) orelse return error.NoZeroRttDatagram;
    defer std.testing.allocator.free(dg);

    var server = try Connection.init(std.testing.allocator, .server, .{});
    defer server.deinit();
    try server.installZeroRttTrafficSecrets(.{ .peer = secrets.client.secret });
    try server.confirmHandshake();
    try server.validatePeerAddress();
    try server.acceptZeroRtt();
    try server.processProtectedZeroRttDatagramWithInstalledKeys(0, dg);

    var buf: [64]u8 = undefined;
    const n = try server.recvOnStream(sid, &buf);
    try std.testing.expectEqual(@as(?usize, 10), n);
    try std.testing.expectEqualStrings("early-data", buf[0..n.?]);
}
